var CONTINUT_ANALIZA={};
CONTINUT_ANALIZA["teorema-valorii-intermediare"]={definitie:"<div class=\"def-box\"><strong>Ipoteză:</strong> Fie f funcție continuă pe [a,b] cu f(a)≠f(b).<br><br><strong>Concluzie:</strong> Pentru orice k strict între f(a) și f(b), există cel puțin un c∈(a,b) cu f(c)=k.</div>",formula_display:"∀k∈(min(f(a),f(b)), max(f(a),f(b))): ∃c∈(a,b) cu f(c)=k",diagrama:"<svg viewBox=\"0 0 340 210\" xmlns=\"http://www.w3.org/2000/svg\" width=\"320\"><line x1=\"50\" y1=\"185\" x2=\"50\" y2=\"22\" stroke=\"#1a1510\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><line x1=\"42\" y1=\"30\" x2=\"50\" y2=\"20\" stroke=\"#1a1510\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><line x1=\"58\" y1=\"30\" x2=\"50\" y2=\"20\" stroke=\"#1a1510\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><line x1=\"50\" y1=\"120\" x2=\"325\" y2=\"120\" stroke=\"#1a1510\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><line x1=\"315\" y1=\"112\" x2=\"325\" y2=\"120\" stroke=\"#1a1510\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><line x1=\"315\" y1=\"128\" x2=\"325\" y2=\"120\" stroke=\"#1a1510\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><text x=\"328\" y=\"124\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">x</text><text x=\"38\" y=\"18\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">f(x)</text><path d=\"M 90,165 C 130,178 155,78 190,120 C 225,162 255,48 290,62\" fill=\"none\" stroke=\"#1e3a5f\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><line x1=\"90\" y1=\"120\" x2=\"90\" y2=\"165\" stroke=\"#aaa\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><line x1=\"290\" y1=\"62\" x2=\"290\" y2=\"120\" stroke=\"#aaa\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><line x1=\"190\" y1=\"90\" x2=\"190\" y2=\"120\" stroke=\"#aaa\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><line x1=\"50\" y1=\"165\" x2=\"90\" y2=\"165\" stroke=\"#aaa\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><line x1=\"50\" y1=\"62\" x2=\"290\" y2=\"62\" stroke=\"#aaa\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><circle cx=\"90\" cy=\"165\" r=\"4\" fill=\"#8b1a1a\" stroke=\"#fff\" stroke-width=\"1.5\"/><circle cx=\"290\" cy=\"62\" r=\"4\" fill=\"#2d5a3d\" stroke=\"#fff\" stroke-width=\"1.5\"/><circle cx=\"190\" cy=\"120\" r=\"4.5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"90\" y=\"135\" text-anchor=\"middle\" font-size=\"12\" font-style=\"italic\" fill=\"#555\">a</text><text x=\"190\" y=\"135\" text-anchor=\"middle\" font-size=\"12\" font-style=\"italic\" fill=\"#c8922a\" font-weight=\"600\">c</text><text x=\"290\" y=\"135\" text-anchor=\"middle\" font-size=\"12\" font-style=\"italic\" fill=\"#555\">b</text><text x=\"42\" y=\"168\" text-anchor=\"end\" font-size=\"11\" font-style=\"italic\" fill=\"#8b1a1a\">f(a)</text><text x=\"42\" y=\"65\" text-anchor=\"end\" font-size=\"11\" font-style=\"italic\" fill=\"#2d5a3d\">f(b)</text><text x=\"42\" y=\"123\" text-anchor=\"end\" font-size=\"11\" fill=\"#999\">0</text><text x=\"192\" y=\"112\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\" font-family=\"'JetBrains Mono',monospace\">f(c)=k</text><text x=\"170\" y=\"200\" text-anchor=\"middle\" font-size=\"11\" fill=\"#999\" font-style=\"italic\">f(a) &lt; 0 &lt; f(b) → ∃c cu f(c) = 0</text></svg>",intuitiv_text:"Dacă temperatura de dimineață a fost −5°C și acum este +20°C, la un moment a trecut prin exact <span class=\"hl\">0°C</span>. O funcție continuă nu poate sări peste valori intermediare.",intuitiv_nota:"Metoda bisecției - algoritmul care găsește numeric rădăcinile funcțiilor - se bazează direct pe această teoremă.",exercitii:[{"q":"f(x)=x²-2 pe [1,2]. Există zero?","pasi":["Evaluăm f la capetele intervalului: f(1)=-1&lt;0 și f(2)=2&gt;0.","Cum f e continuă (fiind polinomială) și își schimbă semnul pe [1,2], teorema valorii intermediare garantează un punct c∈(1,2) cu f(c)=0."],"r":"✓ Da, c=√2≈<strong>1.414</strong>"},{"q":"f(x)=x³-x-1 pe [1,2]. Există zero?","pasi":["Calculăm valorile la capete: f(1)=-1&lt;0, iar f(2)=5&gt;0.","Semnul se schimbă pe interval, iar f e continuă, deci există cel puțin un c∈(1,2) cu f(c)=0."],"r":"✓ Da, c≈<strong>1.3247</strong>"},{"q":"f(x)=x²+1 pe [-1,1]. Există c cu f(c)=0?","pasi":["La capete, f(-1)=2&gt;0 și f(1)=2&gt;0 - nicio schimbare de semn.","De fapt f(x)=x²+1≥1 pentru orice x real, deci graficul nu coboară niciodată până la 0."],"r":"✓ <strong>Nu</strong>. f≥1 mereu."},{"q":"f(x)=cos(x)-x pe [0,π/2]. Există zero?","pasi":["Aici f(0)=1&gt;0, iar f(π/2)≈-1.57&lt;0.","Cum f e continuă și schimbă semn pe interval, teorema valorii intermediare garantează un c∈(0,π/2) cu f(c)=0."],"r":"✓ Da, c≈<strong>0.739 rad</strong>"},{"q":"f(x)=eˣ-3x pe [0,2]. Câte zerouri?","pasi":["Evaluăm f în trei puncte: f(0)=1&gt;0, f(1)≈-0.28&lt;0, f(2)≈1.39&gt;0.","Semnul se schimbă de două ori - întâi între 0 și 1, apoi între 1 și 2 - deci teorema valorii intermediare garantează cel puțin două zerouri pe acest interval."],"r":"✓ <strong>Cel puțin 2</strong> zerouri"}]};
CONTINUT_ANALIZA["teorema-lui-rolle"]={definitie:"<div class=\"def-box\"><strong>Ipoteză:</strong> f continuă pe [a,b], derivabilă pe (a,b) și f(a)=f(b).<br><br><strong>Concluzie:</strong> există cel puțin un punct c∈(a,b) cu f'(c)=0.</div>",formula_display:"f(a)=f(b) → ∃c∈(a,b): f'(c)=0",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 70,120 C 110,40 230,40 270,120\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><line x1=\"70\" y1=\"170\" x2=\"70\" y2=\"120\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"270\" y1=\"170\" x2=\"270\" y2=\"120\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"40\" y1=\"120\" x2=\"270\" y2=\"120\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"140\" y1=\"45\" x2=\"205\" y2=\"45\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/><circle cx=\"70\" cy=\"120\" r=\"4\" fill=\"#4a1a7a\"/><circle cx=\"270\" cy=\"120\" r=\"4\" fill=\"#4a1a7a\"/><circle cx=\"172\" cy=\"45\" r=\"4.5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"70\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">a</text><text x=\"270\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">b</text><text x=\"172\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c8922a\" font-weight=\"600\" font-style=\"italic\">c</text><text x=\"30\" y=\"123\" text-anchor=\"end\" font-size=\"11\" fill=\"#555\">f(a)=f(b)</text><text x=\"172\" y=\"33\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">f'(c)=0</text></svg>",intuitiv_text:"<span class=\"hl\">Aruncă o minge în sus: pleacă din mâna ta și se întoarce tot acolo</span>. Undeva, sus, în vârful traseului, viteza ei a fost exact zero, chiar dacă doar pentru o clipă.",intuitiv_nota:"Este cazul particular al teoremei Lagrange pentru f(a)=f(b). Michel Rolle a demonstrat-o în 1691, deși inițial critica dur calculul infinitezimal.",exercitii:[{"q":"f(x)=x²-4x+3 pe [1,3]. Găsește punctul c unde tangenta e orizontală.","pasi":["Verificăm ipoteza: f(1)=0 și f(3)=0, deci f(1)=f(3) - condiția Rolle e îndeplinită.","Derivăm: f'(x)=2x-4.","Punem derivata egală cu zero: 2x-4=0, deci x=2, care se află în intervalul (1,3)."],"r":"✓ c=<strong>2</strong>"},{"q":"Parabola f(x)=x²-6x+8 are vârful (tangentă orizontală) în c=3. Găsește un interval [a,b] simetric față de c pe care Rolle garantează acest lucru.","pasi":["O parabolă este simetrică față de vârful ei, deci alegem a și b la aceeași distanță de c=3, de exemplu a=1 și b=5.","Verificăm: f(1)=1-6+8=3 și f(5)=25-30+8=3, deci f(1)=f(5) - ipoteza e satisfăcută.","Rolle garantează atunci un punct c∈(1,5) cu f'(c)=0, anume chiar c=3."],"r":"✓ Intervalul <strong>[1,5]</strong> funcționează, cu c=<strong>3</strong>"},{"q":"f(x)=5 (funcție constantă) pe [0,3]. Câte puncte c satisfac f'(c)=0?","pasi":["O funcție constantă are f(0)=f(3)=5, deci ipoteza Rolle e trivial satisfăcută.","Derivata unei constante este zero peste tot: f'(x)=0 pentru orice x din interval."],"r":"✓ <strong>Toate</strong> punctele din (0,3) satisfac f'(c)=0"},{"q":"f(x)=|x| pe [-1,1]. Se poate aplica teorema lui Rolle?","pasi":["Verificăm capetele: f(-1)=1 și f(1)=1, deci f(-1)=f(1) - această condiție e îndeplinită.","Dar f nu este derivabilă în x=0 (graficul are un „colț” ascuțit acolo), deci ipoteza de derivabilitate pe tot intervalul deschis nu este satisfăcută."],"r":"✓ <strong>Nu se aplică</strong> - lipsește derivabilitatea în 0"},{"q":"O minge e aruncată vertical în sus și revine în mână după exact 4 secunde. Arată că a existat un moment cu viteza exact 0.","pasi":["Fie h(t) înălțimea mingii; h(0)=0 (pleacă din mână) și h(4)=0 (revine în mână), deci h(0)=h(4).","h este continuă și derivabilă (mișcarea e netedă), deci ipotezele Rolle sunt îndeplinite pe [0,4].","Rolle garantează un moment c∈(0,4) cu h'(c)=0, adică viteza verticală s-a anulat exact în punctul cel mai înalt al traiectoriei."],"r":"✓ <strong>Da</strong> - la vârful traiectoriei viteza a fost exact 0"}]};
CONTINUT_ANALIZA["teorema-valorii-medii-lagrange"]={definitie:"<div class=\"def-box\"><strong>Ipoteză:</strong> f continuă pe [a,b], derivabilă pe (a,b).<br><br><strong>Concluzie:</strong> există c∈(a,b) unde derivata egalează rata medie de variație.</div>",formula_display:"∃c∈(a,b): f'(c) = (f(b)-f(a))/(b-a)",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 70,150 C 120,70 210,55 270,60\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><line x1=\"70\" y1=\"150\" x2=\"270\" y2=\"60\" stroke=\"#999\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><line x1=\"138\" y1=\"88\" x2=\"212\" y2=\"56\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"70\" cy=\"150\" r=\"4\" fill=\"#4a1a7a\"/><circle cx=\"270\" cy=\"60\" r=\"4\" fill=\"#4a1a7a\"/><circle cx=\"175\" cy=\"68\" r=\"4.5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"70\" y=\"168\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">a</text><text x=\"270\" y=\"168\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">b</text><text x=\"175\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c8922a\" font-weight=\"600\" font-style=\"italic\">c</text><text x=\"228\" y=\"95\" font-size=\"10\" fill=\"#999\" font-style=\"italic\">secantă (viteza medie)</text><text x=\"150\" y=\"43\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">tangentă paralelă în c</text></svg>",intuitiv_text:"<span class=\"hl\">La un moment al călătoriei, viteza instantanee egalează viteza medie</span>. Dacă ai parcurs 120km în 2h, la un moment ai avut exact 60km/h.",intuitiv_nota:"Stă la baza regulii lui L'Hôpital, a inegalităților și a estimărilor de eroare în metode numerice.",exercitii:[{"q":"f(x)=x² pe [1,3]. Găsește punctul c garantat de TVM.","pasi":["Calculăm rata medie de variație: panta secantei = (f(3)-f(1))/(3-1) = (9-1)/2 = 4.","Derivăm: f'(x)=2x.","Egalăm derivata cu panta medie: 2x=4, deci x=2, care se află în (1,3)."],"r":"✓ c=<strong>2</strong>"},{"q":"Pentru f(x)=x² pe [0,b], TVM garantează un punct c=b/2 (verifică). Dacă se știe că c=3, cât este b?","pasi":["Panta medie pe [0,b] este (b²-0)/(b-0)=b.","Egalăm cu derivata: 2x=b, deci x=b/2 - acesta este punctul c, indiferent de b.","Punem c=b/2=3, deci b=6."],"r":"✓ b=<strong>6</strong>"},{"q":"f(x)=7 (funcție constantă) pe [1,5]. Ce spune TVM despre existența lui c?","pasi":["Rata medie de variație este (7-7)/(5-1)=0.","Derivata unei constante este 0 în orice punct, deci f'(c)=0=panta medie pentru orice c din (1,5)."],"r":"✓ <strong>Orice</strong> punct din (1,5) satisface concluzia TVM"},{"q":"f(x)=|x| pe [-1,1]. Se poate aplica TVM (Lagrange)?","pasi":["f este continuă pe [-1,1], deci prima ipoteză e îndeplinită.","Dar f nu e derivabilă în x=0 (colț ascuțit), deci ipoteza de derivabilitate pe (-1,1) nu este satisfăcută."],"r":"✓ <strong>Nu se aplică</strong> - lipsește derivabilitatea în 0"},{"q":"O mașină parcurge 90km în exact 1 oră, pe un drum cu limită de viteză 80km/h. Arată că șoferul a depășit limita la un moment dat.","pasi":["Fie s(t) poziția mașinii; viteza medie pe cel 1 oră este (90-0)/(1-0)=90km/h.","s este continuă și derivabilă (mișcare fizică), deci TVM se aplică pe [0,1].","TVM garantează un moment c cu viteza instantanee s'(c) exact egală cu media, adică 90km/h, care depășește limita de 80km/h."],"r":"✓ <strong>Da</strong> - a existat un moment cu viteza exact 90km/h"}]};
CONTINUT_ANALIZA["teorema-lui-lhopital"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă lim f(x)=lim g(x)=0 sau ±∞ și g'≠0, atunci lim f/g=lim f'/g' dacă ultima limită există.</div>",formula_display:"lim f(x)/g(x) = lim f'(x)/g'(x) (forme 0/0, ∞/∞)",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"190\" y1=\"170\" x2=\"190\" y2=\"30\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><path d=\"M 80,55 C 130,105 165,150 190,170 C 215,190 250,196 280,198\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><path d=\"M 80,120 C 130,148 165,163 190,170 C 215,177 250,181 280,183\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"190\" cy=\"170\" r=\"4.5\" fill=\"#1a1510\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"190\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">a</text><text x=\"255\" y=\"196\" font-size=\"11\" fill=\"#4a1a7a\" font-style=\"italic\">f(x)</text><text x=\"255\" y=\"178\" font-size=\"11\" fill=\"#c8922a\" font-style=\"italic\">g(x)</text><text x=\"60\" y=\"45\" font-size=\"10\" fill=\"#999\">f(a)=g(a)=0</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă doi alergători ajung exact în același moment la linia de sosire, distanța rămasă la amândoi e 0 - nu spune nimic despre cine era mai rapid</span>. Ca să compari, te uiți la vitezele lor chiar înainte de linie, nu la distanțe. Asta face L'Hôpital: compară derivatele (vitezele) în loc de valorile (distanțele), amândouă 0.",intuitiv_nota:"L'Hôpital nu a descoperit teorema - a cumpărat-o de la Johann Bernoulli în 1696. Nu se aplică direct pentru 0×∞, ∞-∞, 0⁰, 1^∞ sau ∞⁰ - acestea trebuie transformate mai întâi în 0/0 sau ∞/∞.",exercitii:[{"q":"Calculează lim(x→0) sinx/x.","pasi":["Verificăm forma: sin(0)=0 și x→0, deci avem forma nedeterminată 0/0.","Derivăm separat numărătorul și numitorul: (sinx)'=cosx, (x)'=1.","Limita raportului derivatelor este lim cosx/1 = cos(0) = 1."],"r":"✓ <strong>1</strong>"},{"q":"Găsește a astfel încât lim(x→0) sin(ax)/x = 3.","pasi":["Forma este 0/0, deci aplicăm L'Hôpital: derivăm numărătorul, (sin(ax))'=a·cos(ax), și numitorul, (x)'=1.","Limita devine lim a·cos(ax)/1 = a·cos(0) = a.","Punem a=3, deci limita cerută se obține pentru a=3."],"r":"✓ a=<strong>3</strong>"},{"q":"Calculează lim(x→0) (1-cosx)/x² (necesită L'Hôpital aplicat de două ori).","pasi":["Forma e 0/0. Derivăm: (1-cosx)'=sinx, (x²)'=2x, obținem lim sinx/(2x).","Acesta e tot 0/0, deci derivăm din nou: (sinx)'=cosx, (2x)'=2.","Limita finală este lim cosx/2 = 1/2."],"r":"✓ <strong>1/2</strong>"},{"q":"lim(x→∞) (x+sinx)/x. Se poate calcula sigur prin L'Hôpital?","pasi":["Forma este ∞/∞, deci teoretic se poate încerca L'Hôpital.","Dar derivând obținem (1+cosx)/1, care oscilează la nesfârșit între 0 și 2 și nu are limită.","L'Hôpital eșuează aici pentru că lipsește ipoteza „limita raportului derivatelor există”; limita reală tot există (calculată direct, prin împărțire la x, este 1), doar că metoda L'Hôpital nu o poate găsi în acest caz."],"r":"✓ L'Hôpital <strong>nu se aplică</strong> aici; limita reală este totuși 1"},{"q":"Populațiile a două insulițe scad amândouă spre 0 exact în anul T. Chiar înainte de T, insula 1 pierde 6000 locuitori/an, iar insula 2 pierde 2000 locuitori/an. Ce spune raportul populațiilor P₁(t)/P₂(t) când t→T?","pasi":["Avem forma 0/0, deoarece ambele populații tind la 0 în același moment T.","Ratele de scădere sunt derivatele: P₁'(T)=-6000, P₂'(T)=-2000.","Prin L'Hôpital, lim P₁(t)/P₂(t) = P₁'(T)/P₂'(T) = -6000/-2000 = 3."],"r":"✓ Raportul tinde la <strong>3</strong> (insula 1 dispare de 3 ori „mai repede” relativ)"}]};
CONTINUT_ANALIZA["formula-lui-taylor"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice funcție suficient de derivabilă se aproximează printr-un polinom cu coeficienți dați de derivatele sale în punctul a.</div>",formula_display:"f(x) = ∑_{k=0}^n f⁽ᵏ⁾(a)/k!·(x-a)ᵏ + Rₙ",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 60,150 C 110,120 150,60 180,55 C 220,48 250,70 280,40\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><path d=\"M 110,135 Q 180,50 250,95\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2.5\" stroke-dasharray=\"6,4\"/><line x1=\"180\" y1=\"170\" x2=\"180\" y2=\"55\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><circle cx=\"180\" cy=\"55\" r=\"4.5\" fill=\"#1a1510\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"180\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">a</text><text x=\"240\" y=\"32\" font-size=\"11\" fill=\"#4a1a7a\" font-style=\"italic\">f(x)</text><text x=\"235\" y=\"108\" font-size=\"11\" fill=\"#c8922a\" font-style=\"italic\">polinom Taylor</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă știi exact unde ești, cât de repede te miști și cum se schimbă viteza ta chiar acum, poți ghici destul de bine unde vei fi peste o clipă</span> - fără să cunoști tot drumul dinainte. Polinomul Taylor face exact asta: folosește valoarea, viteza (derivata) și accelerația (derivata a doua) dintr-un punct pentru a ghici funcția în apropiere.",intuitiv_nota:"Brook Taylor a publicat formula în 1715. Restul Lagrange permite estimarea erorii aproximării - esențial în analiza numerică și în calculatoarele care evaluează sin, cos, eˣ prin polinoame.",exercitii:[{"q":"Scrie polinomul Taylor de grad 3 pentru eˣ în jurul lui x=0.","pasi":["Toate derivatele lui eˣ sunt eˣ, deci în x=0 fiecare derivată valorează e⁰=1.","Coeficienții sunt f⁽ᵏ⁾(0)/k! = 1/k!, adică 1, 1, 1/2, 1/6 pentru k=0,1,2,3.","Polinomul este 1+x+x²/2+x³/6."],"r":"✓ <strong>1+x+x²/2+x³/6</strong>"},{"q":"Ce grad minim n garantează o eroare mai mică de 0.001 la aproximarea sin(0.5) cu polinomul Taylor în jurul lui 0?","pasi":["Termenii seriei sin(x)=x-x³/6+x⁵/120-... au eroarea mărginită de valoarea absolută a următorului termen neglijat.","Cu n=1 (doar x), eroarea e cel mult 0.5³/6≈0.021 - prea mare.","Cu n=3 (x-x³/6), următorul termen neglijat e x⁵/120, deci eroarea e cel mult 0.5⁵/120≈0.00026&lt;0.001 - suficient."],"r":"✓ Gradul minim necesar este <strong>n=3</strong>"},{"q":"Scrie polinomul Taylor de grad 2 pentru f(x)=x²-3x+2 în jurul lui a=1. Ce observi?","pasi":["f(1)=0, f'(x)=2x-3 deci f'(1)=-1, f''(x)=2 deci f''(1)=2.","Polinomul Taylor: 0+(-1)(x-1)+2/2·(x-1)²=-(x-1)+(x-1)².","Dezvoltând, acesta este exact x²-3x+2 - identic cu f, fără nicio eroare (restul e 0)."],"r":"✓ Pentru un <strong>polinom</strong>, seria Taylor de grad suficient de mare reproduce exact funcția, cu rest 0"},{"q":"Adevărat sau fals: cu cât gradul polinomului Taylor crește, aproximarea devine mereu mai bună pe tot domeniul funcției, oricât de departe de a.","pasi":["Fals în general - aproximarea e garantat bună doar în interiorul razei de convergență a seriei.","Exemplu: seria Taylor a lui ln(1+x) în jurul lui 0 are raza de convergență 1, deci pentru x&gt;1 sau x≤-1 seria nu mai converge către funcție, indiferent de gradul folosit."],"r":"✓ <strong>Fals</strong> - aproximarea e de încredere doar în raza de convergență"},{"q":"La ora 12:00 termometrul arată 20°C, temperatura crește cu 2°C/oră, iar rata de creștere însăși încetinește (a doua derivată este -0.5°C/oră²). Estimează temperatura la ora 13:00 cu Taylor de gradul 2.","pasi":["Notăm T(0)=20 (valoare), T'(0)=2 (viteza de creștere), T''(0)=-0.5 (încetinirea).","Polinomul Taylor de gradul 2: T(t)≈T(0)+T'(0)·t+T''(0)/2·t².","Pentru t=1 oră: T(1)≈20+2·1+(-0.5)/2·1²=20+2-0.25=21.75°C."],"r":"✓ Temperatura estimată la 13:00 este <strong>≈21.75°C</strong>"}]};
CONTINUT_ANALIZA["teorema-fundamentala-a-calculului"]={definitie:"<div class=\"def-box\"><strong>Enunț (Leibniz-Newton):</strong> Dacă f continuă pe [a,b] și F(x)=∫ₐˣf(t)dt, atunci F'(x)=f(x). Mai mult: ∫ₐᵇf(x)dx=F(b)-F(a).</div>",formula_display:"d/dx ∫ₐˣ f(t)dt = f(x)",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 60,140 C 110,60 190,40 280,70\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><path d=\"M 60,170 L 60,140 C 90,110 120,80 150,68 L 150,170 Z\" fill=\"#c8922a\" fill-opacity=\"0.35\" stroke=\"none\"/><line x1=\"60\" y1=\"170\" x2=\"60\" y2=\"140\" stroke=\"#4a1a7a\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"150\" y1=\"170\" x2=\"150\" y2=\"68\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><text x=\"60\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">a</text><text x=\"150\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c8922a\" font-weight=\"600\" font-style=\"italic\">x</text><text x=\"95\" y=\"150\" font-size=\"11\" fill=\"#c8922a\" font-weight=\"600\">F(x)</text><text x=\"255\" y=\"60\" font-size=\"11\" fill=\"#4a1a7a\" font-style=\"italic\">f(t)</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă f(t) e viteza cu care curge apa într-o cadă la momentul t, atunci F(x) e cât de multă apă s-a strâns până la momentul x</span>. Cât de repede crește cantitatea de apă chiar acum (derivata lui F) este exact viteza curgerii chiar acum, f(x) - de aceea derivarea „desface” integrarea.",intuitiv_nota:"Newton și Leibniz au descoperit independent această legătură fundamentală între 1668 și 1686. TFC permite calculul integralelor prin primitive și stă la baza întregului calcul integral.",exercitii:[{"q":"Calculează ∫₀² 3x² dx.","pasi":["Găsim o primitivă a lui 3x²: F(x)=x³ (verificăm: F'(x)=3x², corect).","Aplicăm TFC: integrala este F(2)-F(0).","F(2)-F(0)=8-0=8."],"r":"✓ <strong>8</strong>"},{"q":"Pentru ce valoare a lui a (a&gt;0) avem ∫₀^a 2x dx = 16?","pasi":["O primitivă a lui 2x este F(x)=x², deci ∫₀^a 2x dx = F(a)-F(0) = a²-0 = a².","Punem condiția a²=16.","Cum a&gt;0, rezultă a=4."],"r":"✓ a=<strong>4</strong>"},{"q":"Cât este ∫₃³ f(x) dx pentru orice funcție continuă f?","pasi":["Intervalul de integrare are lungime 0 (limita superioară coincide cu cea inferioară).","Prin TFC, integrala este F(3)-F(3), unde F e o primitivă a lui f.","F(3)-F(3)=0, indiferent de f."],"r":"✓ <strong>0</strong> - integrala pe un interval degenerat e mereu nulă"},{"q":"f(t)=0 pentru t&lt;1 și f(t)=1 pentru t≥1 (are un salt în t=1). F(x)=∫₀ˣf(t)dt. Este F derivabilă în x=1 cu F'(1)=f(1)?","pasi":["Calculăm F explicit: F(x)=0 pentru x≤1, iar F(x)=x-1 pentru x&gt;1.","Derivata la stânga în x=1 este 0, iar derivata la dreapta este 1 - cele două nu coincid.","TFC cere ca f să fie continuă în punctul respectiv pentru ca F'=f acolo; la saltul lui f, ipoteza nu e satisfăcută."],"r":"✓ <strong>Nu</strong> - F are un „colț” în x=1, nu e derivabilă acolo"},{"q":"O colonie de bacterii crește cu rata r(t)=1000·e^(0.1t) bacterii/oră. Câte bacterii noi s-au adăugat în primele 5 ore?","pasi":["Numărul de bacterii noi este ∫₀⁵ r(t) dt, adică aria de sub graficul ratei.","O primitivă a lui 1000·e^(0.1t) este 10000·e^(0.1t) (verificăm: derivata dă înapoi 1000·e^(0.1t)).","Aplicăm TFC: 10000·e^(0.5)-10000·e^0 = 10000·(1.6487-1) ≈ 6487."],"r":"✓ ≈<strong>6487</strong> bacterii noi"}]};
CONTINUT_ANALIZA["regula-lantului-derivate"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă g e derivabilă în x și f e derivabilă în g(x), derivata compusei f∘g este produsul derivatelor.</div>",formula_display:"(f∘g)'(x) = f'(g(x)) · g'(x)",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"60\" y1=\"170\" x2=\"60\" y2=\"30\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"170\" y1=\"170\" x2=\"170\" y2=\"30\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"280\" y1=\"170\" x2=\"280\" y2=\"30\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><circle cx=\"60\" cy=\"110\" r=\"4.5\" fill=\"#c8922a\"/><circle cx=\"170\" cy=\"80\" r=\"4.5\" fill=\"#c8922a\"/><circle cx=\"280\" cy=\"55\" r=\"4.5\" fill=\"#c8922a\"/><path d=\"M 68,108 Q 115,70 162,81\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2\"/><polygon points=\"162,81 152,77 155,86\" fill=\"#4a1a7a\"/><path d=\"M 178,79 Q 225,50 272,56\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2\"/><polygon points=\"272,56 262,53 264,62\" fill=\"#4a1a7a\"/><text x=\"60\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">x</text><text x=\"170\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">u=g(x)</text><text x=\"280\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">y=f(u)</text><text x=\"110\" y=\"65\" text-anchor=\"middle\" font-size=\"11\" fill=\"#4a1a7a\" font-weight=\"600\">g'(x)</text><text x=\"220\" y=\"40\" text-anchor=\"middle\" font-size=\"11\" fill=\"#4a1a7a\" font-weight=\"600\">f'(u)</text><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">(f∘g)'(x)=f'(u)·g'(x)</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă o roată dințată se rotește de 2 ori mai repede decât motorul, iar o a doua roată legată de prima se rotește de 3 ori mai repede decât ea, roata finală se rotește de 2×3=6 ori mai repede decât motorul</span>. Așa se înmulțesc „vitezele de schimbare” când o funcție e legată în lanț de alta.",intuitiv_nota:"Poate cea mai folosită regulă de derivare - apare în aproape orice calcul real. Backpropagation din rețelele neuronale este aplicarea repetată a regulii lanțului, de multe ori la rând.",exercitii:[{"q":"Calculează derivata funcției h(x)=sin(x²).","pasi":["Identificăm compunerea: h=f∘g, unde f(u)=sin(u) (exterior) și g(x)=x² (interior).","Derivăm exteriorul, păstrând interiorul neschimbat: f'(u)=cos(u), deci f'(g(x))=cos(x²).","Înmulțim cu derivata interiorului: g'(x)=2x. Rezultat: h'(x)=2x·cos(x²)."],"r":"✓ <strong>2x·cos(x²)</strong>"},{"q":"O funcție compusă h(x)=f(3x+1) are h'(x)=6(3x+1). Ce este f'(t)?","pasi":["Prin regula lanțului, h'(x)=f'(3x+1)·(3x+1)'=f'(3x+1)·3.","Comparăm cu h'(x)=6(3x+1): rezultă f'(3x+1)·3=6(3x+1), deci f'(3x+1)=2(3x+1).","Notând t=3x+1, obținem f'(t)=2t pentru orice t."],"r":"✓ <strong>f'(t)=2t</strong>"},{"q":"Fie g(x)=5 (funcție constantă) și f o funcție oarecare derivabilă. Cât este (f∘g)'(x)?","pasi":["Compunerea este h(x)=f(g(x))=f(5), care e o constantă, indiferent de x.","Derivata unei constante este 0.","Verificare cu formula: g'(x)=0 (derivata unei constante), deci f'(g(x))·g'(x)=f'(5)·0=0 - același rezultat."],"r":"✓ <strong>0</strong> - compunerea cu o funcție constantă are derivată nulă"},{"q":"Adevărat sau fals: (f∘g)'(x) = f'(x)·g'(x), adică derivatele se înmulțesc direct, fără compunere.","pasi":["Fals - este o greșeală frecventă. Formula corectă este f'(g(x))·g'(x): derivata lui f se evaluează în g(x), nu în x.","Exemplu concret: pentru h(x)=sin(x²), formula greșită ar da cos(x)·2x, complet diferit de rezultatul corect 2x·cos(x²)."],"r":"✓ <strong>Fals</strong> - f' trebuie evaluată în g(x), nu în x"},{"q":"Temperatura scade cu altitudinea după T(h)=15-0.0065h (°C, h în metri), iar un balon urcă cu viteza h(t)=50t (metri, t în minute). Cât de repede scade temperatura resimțită de balon, în funcție de timp?","pasi":["Temperatura resimțită depinde de timp prin altitudine: T(h(t)) este o compunere de funcții.","Regula lanțului: dT/dt = dT/dh · dh/dt.","dT/dh=-0.0065 (rata de scădere cu altitudinea) și dh/dt=50 (viteza balonului), deci dT/dt=-0.0065·50=-0.325°C/minut."],"r":"✓ Temperatura scade cu <strong>0.325°C în fiecare minut</strong>"}]};
CONTINUT_ANALIZA["integrarea-prin-parti"]={definitie:"<div class=\"def-box\"><strong>Formulă:</strong> ∫u·v' dx = u·v - ∫u'·v dx (analogul integral al derivatei produsului).</div>",formula_display:"∫u·dv = u·v − ∫v·du",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><path d=\"M 40,170 Q 140,150 200,90 Q 230,55 260,30 L 260,170 Z\" fill=\"#4a1a7a\" fill-opacity=\"0.25\" stroke=\"none\"/><path d=\"M 40,170 Q 140,150 200,90 Q 230,55 260,30 L 40,30 Z\" fill=\"#c8922a\" fill-opacity=\"0.25\" stroke=\"none\"/><path d=\"M 40,170 Q 140,150 200,90 Q 230,55 260,30\" fill=\"none\" stroke=\"#1a1510\" stroke-width=\"2\"/><rect x=\"40\" y=\"30\" width=\"220\" height=\"140\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"260\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">u</text><text x=\"22\" y=\"34\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">v</text><text x=\"120\" y=\"163\" font-size=\"11\" fill=\"#4a1a7a\" font-weight=\"600\">∫v du</text><text x=\"60\" y=\"55\" font-size=\"11\" fill=\"#c8922a\" font-weight=\"600\">∫u dv</text><text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">u·v = ∫v du + ∫u dv</text></svg>",intuitiv_text:"<span class=\"hl\">Gândește-te la aria unui dreptunghi cu laturile u și v</span>. Dacă tragi o linie curbă prin el, dreptunghiul se împarte în două bucăți: aria de sub curbă și aria de lângă curbă. Suma lor este exact aria întregului dreptunghi, u·v - de aici vine formula integrării prin părți.",intuitiv_nota:"Regula LIATE (Logaritm, Invers trigonometric, Algebric, Trigonometric, Exponențial) ajută la alegerea lui u - alege prima funcție din listă care apare în produs. Metoda se poate aplica repetat sau chiar circular (rezolvând o ecuație pentru integrala căutată).",exercitii:[{"q":"Calculează ∫x·eˣ dx.","pasi":["Alegem u=x (se simplifică prin derivare) și dv=eˣdx (ușor de integrat); atunci du=dx și v=eˣ.","Aplicăm formula: ∫x·eˣdx = x·eˣ - ∫eˣdx.","Integrăm ce a rămas: x·eˣ - eˣ + C."],"r":"✓ <strong>(x-1)eˣ+C</strong>"},{"q":"Ce integrală de forma ∫x·(...)dx are ca rezultat x·sinx+cosx+C?","pasi":["Derivăm rezultatul propus pentru a găsi integrandul: d/dx(x·sinx+cosx) = sinx+x·cosx-sinx = x·cosx.","Deci integrandul căutat este x·cosx.","Verificăm prin părți: u=x, dv=cosx dx, v=sinx; ∫x·cosx dx = x·sinx - ∫sinx dx = x·sinx+cosx+C. ✔"],"r":"✓ Integrala căutată este <strong>∫x·cosx dx</strong>"},{"q":"Calculează ∫ₐᵃ x·eˣ dx (interval degenerat, aceeași limită sus și jos).","pasi":["Indiferent de metoda de integrare, o integrală definită pe un interval de lungime 0 este întotdeauna 0.","Prin părți am obținea aceeași primitivă F(x)=(x-1)eˣ, iar F(a)-F(a)=0."],"r":"✓ <strong>0</strong> - integrala pe un interval degenerat e mereu nulă"},{"q":"Adevărat sau fals: alegerea lui u și dv la integrarea prin părți este arbitrară și nu influențează cât de ușor este calculul.","pasi":["Fals. La ∫x·eˣdx, dacă alegem greșit u=eˣ și dv=x dx, obținem v=x²/2, iar formula dă (x²/2)eˣ - ∫(x²/2)eˣdx.","Noua integrală are un polinom de grad mai mare (x² în loc de x), deci calculul devine mai complicat, nu mai simplu.","Regula LIATE există tocmai ca să ghideze spre alegerea care simplifică, nu complică, integrala rămasă."],"r":"✓ <strong>Fals</strong> - alegerea greșită poate complica mult calculul"},{"q":"O populație de insecte are rata de creștere r(t)=t·e^(−t) (mii insecte/lună) - creștere inițială rapidă, urmată de declin. Câte insecte noi (în mii) s-au adăugat în primele 2 luni?","pasi":["Numărul de insecte noi este ∫₀² t·e^(−t) dt. Alegem u=t, dv=e^(−t)dt, deci du=dt, v=-e^(−t).","Aplicăm formula: ∫t·e^(−t)dt = -t·e^(−t) + ∫e^(−t)dt = -t·e^(−t) - e^(−t) + C = -(t+1)e^(−t)+C.","Evaluăm între 0 și 2: [-(t+1)e^(−t)]₀² = -3e^(−2) - (-1) = 1-3e^(−2) ≈ 1-0.406 ≈ 0.594."],"r":"✓ ≈<strong>0.594 mii</strong> (≈594 insecte noi)"}]};
CONTINUT_ANALIZA["seria-geometrica"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Seria geometrică cu primul termen a și rație r converge dacă |r|&lt;1, cu suma S=a/(1-r).</div>",formula_display:"∑_{n=0}^∞ arⁿ = a/(1−r), |r|&lt;1",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><rect x=\"20\" y=\"80\" width=\"280\" height=\"40\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><rect x=\"20\" y=\"80\" width=\"140\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.65\"/><rect x=\"160\" y=\"80\" width=\"70\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.5\"/><rect x=\"230\" y=\"80\" width=\"35\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.35\"/><rect x=\"265\" y=\"80\" width=\"17\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.22\"/><rect x=\"282\" y=\"80\" width=\"9\" height=\"40\" fill=\"#c8922a\" fill-opacity=\"0.6\"/><text x=\"90\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" fill=\"#fff\" font-weight=\"600\">1</text><text x=\"195\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" fill=\"#fff\">1/2</text><text x=\"247\" y=\"103\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">1/4</text><text x=\"150\" y=\"140\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">1+1/2+1/4+1/8+... → suma totală = 2</text><text x=\"150\" y=\"60\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">infinit de termeni, sumă finită</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă ai 1 bomboană, apoi jumătate de bomboană, apoi un sfert, și tot așa la nesfârșit</span>, ai aduna în total exact 2 bomboane - deși faci infinit de multe adăugări, din ce în ce mai mici. Paradoxul lui Zenon se rezolvă exact prin această idee.",intuitiv_nota:"Formula apare în finanțe (valoarea prezentă a unor plăți repetate), probabilitate și fizică (oscilații amortizate, distanța parcursă de o minge care sare).",exercitii:[{"q":"Calculează suma seriei ∑(1/2)ⁿ pentru n de la 0 la infinit.","pasi":["Identificăm a=1 (primul termen, la n=0) și r=1/2 (rația).","Verificăm condiția de convergență: |r|=1/2&lt;1, deci seria converge.","Aplicăm formula: S=a/(1-r)=1/(1-1/2)=1/(1/2)=2."],"r":"✓ S=<strong>2</strong>"},{"q":"O serie geometrică cu primul termen a=3 are suma S=12. Care este rația r?","pasi":["Pornim de la formula S=a/(1-r) și înlocuim valorile cunoscute: 12=3/(1-r).","Rezolvăm pentru (1-r): 1-r=3/12=1/4.","Deci r=1-1/4=3/4."],"r":"✓ r=<strong>3/4</strong>"},{"q":"Calculează suma seriei ∑a·0ⁿ pentru n de la 0 la infinit (rația r=0).","pasi":["Cu r=0, toți termenii de la n=1 încolo sunt 0 (0¹=0, 0²=0, etc.), deci rămâne doar primul termen, a.","Verificare cu formula: S=a/(1-0)=a - același rezultat."],"r":"✓ S=<strong>a</strong> (doar primul termen contează)"},{"q":"Se aplică formula S=a/(1-r) pentru seria ∑3ⁿ (a=1, r=3)? Ce se întâmplă dacă o aplicăm mecanic?","pasi":["Verificăm condiția: |r|=3, care nu este &lt;1, deci seria diverge (termenii cresc la infinit) - formula NU se aplică.","Dacă am aplica-o mecanic am obține S=1/(1-3)=1/(-2)=-1/2 - o „sumă” negativă pentru o serie cu toți termenii pozitivi, ceea ce e absurd.","Acest rezultat fals arată de ce condiția |r|&lt;1 este obligatorie, nu opțională."],"r":"✓ <strong>Nu se aplică</strong> - seria diverge, iar formula ar da un rezultat absurd"},{"q":"O minge cade de la 2m înălțime și, de fiecare dată când atinge solul, sare înapoi la 3/4 din înălțimea precedentă. Ce distanță totală parcurge mingea până se oprește?","pasi":["Înălțimile succesive ale săriturilor formează o serie geometrică: h₁=2·(3/4)=1.5, h₂=1.5·(3/4)=1.125, cu a=1.5 și r=3/4.","Fiecare săritură parcurge distanța în sus și înapoi în jos, deci contribuie cu 2·hₙ la distanța totală. Suma înălțimilor este S=1.5/(1-0.75)=6.","Distanța totală = căderea inițială (2m) + de două ori suma săriturilor (2·6=12m) = 2+12=14m."],"r":"✓ Distanța totală este <strong>14 metri</strong>"}]};
CONTINUT_ANALIZA["criteriul-dalembert"]={definitie:"<div class=\"def-box\"><strong>Criteriul raportului:</strong> Fie ∑aₙ cu aₙ&gt;0. L=lim|aₙ₊₁/aₙ|: convergentă dacă L&lt;1, divergentă dacă L&gt;1, neconcludent dacă L=1.</div>",formula_display:"L = lim|aₙ₊₁/aₙ|: L&lt;1→conv., L&gt;1→div.",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><rect x=\"55\" y=\"50\" width=\"30\" height=\"120\" fill=\"#4a1a7a\" fill-opacity=\"0.7\"/><rect x=\"100\" y=\"95\" width=\"30\" height=\"75\" fill=\"#4a1a7a\" fill-opacity=\"0.6\"/><rect x=\"145\" y=\"125\" width=\"30\" height=\"45\" fill=\"#4a1a7a\" fill-opacity=\"0.5\"/><rect x=\"190\" y=\"145\" width=\"30\" height=\"25\" fill=\"#4a1a7a\" fill-opacity=\"0.4\"/><rect x=\"235\" y=\"158\" width=\"30\" height=\"12\" fill=\"#c8922a\" fill-opacity=\"0.7\"/><text x=\"70\" y=\"185\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">a₁</text><text x=\"115\" y=\"185\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">a₂</text><text x=\"160\" y=\"185\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">a₃</text><text x=\"205\" y=\"185\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">a₄</text><text x=\"250\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">a₅</text><text x=\"150\" y=\"32\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\" font-weight=\"600\">aₙ₊₁/aₙ → L &lt; 1</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă la fiecare pas faci un salt de câteva ori mai mic decât precedentul, iar acest raport se apropie de un număr sub 1, salturile se micșorează destul de repede încât distanța totală rămâne finită</span> - la fel ca la seria geometrică. Criteriul lui D'Alembert funcționează cel mai bine pentru serii cu factoriale și puteri.",intuitiv_nota:"Criteriul eșuează (nu dă niciun răspuns) când L=1 - atunci trebuie folosită altă metodă. Alternativă înrudită: criteriul rădăcinii (Cauchy), care compară ⁿ√aₙ cu 1.",exercitii:[{"q":"Studiază convergența seriei ∑2ⁿ/n! folosind criteriul raportului.","pasi":["Calculăm raportul termenilor consecutivi: aₙ₊₁/aₙ = [2ⁿ⁺¹/(n+1)!]/[2ⁿ/n!] = 2/(n+1).","Trecem la limită: L=lim 2/(n+1) = 0.","Cum L=0&lt;1, seria converge (factorialul „câștigă” mereu în fața puterii)."],"r":"✓ <strong>Convergentă</strong>"},{"q":"Pentru ce valori reale ale lui x converge seria ∑xⁿ/n! (aplicând D'Alembert)?","pasi":["Raportul termenilor: |aₙ₊₁/aₙ| = |x|ⁿ⁺¹/(n+1)! ÷ |x|ⁿ/n! = |x|/(n+1).","Limita este L=lim |x|/(n+1) = 0, indiferent de valoarea lui x.","Cum L=0&lt;1 pentru orice x, seria converge pentru toți x reali - aceasta e de fapt seria lui eˣ."],"r":"✓ Converge pentru <strong>orice x real</strong>"},{"q":"Aplică D'Alembert seriei geometrice generale ∑rⁿ (r&gt;0) și verifică dacă regăsești condiția cunoscută.","pasi":["Raportul termenilor consecutivi: aₙ₊₁/aₙ = rⁿ⁺¹/rⁿ = r, constant, pentru orice n.","La limită obținem L=lim r = r (raportul nu depinde deloc de n).","Regăsim exact condiția de convergență cunoscută: seria geometrică converge dacă și numai dacă r&lt;1 - criteriul D'Alembert e consistent cu ea."],"r":"✓ <strong>L=r</strong>, confirmă condiția r&lt;1"},{"q":"∑1/n² - ce spune criteriul lui D'Alembert? Seria converge totuși?","pasi":["Raportul: aₙ₊₁/aₙ = n²/(n+1)².","Trecând la limită, L=lim n²/(n+1)² = 1.","Cu L=1, criteriul D'Alembert e neconcludent - nu decide nimic. Totuși, seria converge (se poate arăta cu alt criteriu, de exemplu cel al condensării Cauchy sau comparație cu integrala): D'Alembert pur și simplu nu are puterea de a vedea acest lucru."],"r":"✓ <strong>Neconcludent</strong> prin D'Alembert, deși seria de fapt <strong>converge</strong>"},{"q":"Numărul de imigranți noi pe o insulă în anul n este aₙ=500·(0.6)ⁿ. Arată, cu D'Alembert, că numărul total de imigranți de-a lungul timpului este finit, apoi calculează-l.","pasi":["Raportul termenilor: aₙ₊₁/aₙ = 500·(0.6)ⁿ⁺¹/[500·(0.6)ⁿ] = 0.6, constant.","Limita este L=0.6&lt;1, deci seria ∑aₙ converge - numărul total de imigranți e finit.","Fiind o serie geometrică cu a=500·0.6=300 și r=0.6, suma este 300/(1-0.6)=750."],"r":"✓ Total finit: <strong>750</strong> imigranți"}]};
CONTINUT_ANALIZA["criteriul-leibniz"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> O serie alternantă ∑(-1)ⁿaₙ cu aₙ&gt;0 descrescătoare monoton la zero este convergentă.</div>",formula_display:"aₙ↘0 → ∑(-1)ⁿaₙ convergentă",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"100\" x2=\"300\" y2=\"100\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><polyline points=\"50,150 90,60 120,120 145,80 165,110 180,90 192,102 200,95\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/><circle cx=\"50\" cy=\"150\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"90\" cy=\"60\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"120\" cy=\"120\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"145\" cy=\"80\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"165\" cy=\"110\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"180\" cy=\"90\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"192\" cy=\"102\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"200\" cy=\"95\" r=\"4.5\" fill=\"#c8922a\"/><line x1=\"200\" y1=\"100\" x2=\"280\" y2=\"100\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><text x=\"285\" y=\"104\" font-size=\"11\" fill=\"#c8922a\" font-weight=\"600\">L</text><text x=\"50\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">S₁</text><text x=\"90\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">S₂</text><text x=\"145\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">S₄</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă faci un pas mare înainte, apoi unul mai mic înapoi, apoi unul și mai mic înainte, alternând direcția și micșorând mereu pașii, te apropii tot mai mult de un punct fix</span>, fără să-l depășești vreodată cu mult. Sumele parțiale „se strâng” în jurul limitei ca un arc.",intuitiv_nota:"Leibniz a demonstrat convergența pentru ∑(-1)ⁿ⁺¹/n=ln(2), numită seria armonică alternantă. Criteriul dă și o estimare a erorii de trunchiere: eroarea făcută oprindu-te după N termeni este cel mult aₙ₊₁.",exercitii:[{"q":"Arată că seria ∑(-1)ⁿ⁺¹/n converge.","pasi":["Notăm aₙ=1/n. Verificăm: aₙ&gt;0 pentru orice n≥1.","Verificăm monotonia: aₙ₊₁=1/(n+1)&lt;1/n=aₙ, deci șirul e strict descrescător.","Verificăm limita: aₙ=1/n→0. Toate ipotezele Leibniz sunt satisfăcute, deci seria converge (suma este ln2)."],"r":"✓ <strong>Convergentă</strong>, suma=ln(2)≈0.693"},{"q":"Câți termeni trebuie adunați din seria ∑(-1)ⁿ⁺¹/n pentru ca eroarea de aproximare a sumei să fie mai mică de 0.01?","pasi":["Criteriul Leibniz garantează că eroarea după N termeni este cel mult egală cu primul termen neglijat, aₙ₊₁=1/(N+1).","Punem condiția 1/(N+1)&lt;0.01, adică N+1&gt;100.","Rezultă N≥100, deci sunt necesari cel puțin 100 de termeni."],"r":"✓ Sunt necesari cel puțin <strong>100</strong> de termeni"},{"q":"Fie aₙ=1/n pentru n≤4 și aₙ=0 pentru n≥5. Converge seria ∑(-1)ⁿ⁺¹aₙ?","pasi":["După n=4 toți termenii sunt 0, deci suma seriei este de fapt o sumă finită: a₁-a₂+a₃-a₄.","O sumă finită converge întotdeauna (nu există „coadă infinită” care să pună probleme).","Verificare cu Leibniz: aₙ este descrescător și tinde la 0 (fiind constant 0 de la un rang încolo), deci ipotezele sunt satisfăcute trivial."],"r":"✓ <strong>Convergentă</strong> - este de fapt o sumă finită"},{"q":"Converge seria ∑(-1)ⁿ·n?","pasi":["Aici aₙ=n, care nu tinde la 0 - dimpotrivă, aₙ→∞.","Condiția esențială a criteriului Leibniz (aₙ↘0) nu este satisfăcută, deci criteriul nu garantează nimic.","De fapt seria diverge: termenii nu tind la 0, deci nici măcar condiția necesară de convergență (aₙ→0 pentru orice serie) nu e satisfăcută."],"r":"✓ <strong>Divergentă</strong> - aₙ nu tinde la 0"},{"q":"Temperatura unei camere pornește de la 20°C și variază în fiecare oră succesivă cu vₙ=(-1)ⁿ⁺¹·4/n °C (variații tot mai mici, alternând sensul). Se stabilizează temperatura la o valoare limită?","pasi":["Seria variațiilor este ∑(-1)ⁿ⁺¹·4/n = 4·∑(-1)ⁿ⁺¹/n; termenii aₙ=4/n sunt pozitivi, descrescători și tind la 0.","Prin criteriul Leibniz, seria converge, deci temperatura totală se stabilizează la o valoare limită finită.","Folosind ∑(-1)ⁿ⁺¹/n=ln2, limita este 20+4·ln2 ≈ 20+2.77 ≈ 22.77°C."],"r":"✓ Temperatura se stabilizează la <strong>≈22.77°C</strong>"}]};
CONTINUT_ANALIZA["teorema-lui-weierstrass-functii-continue"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice funcție continuă f:[a,b]→ℝ pe un interval compact atinge valorile sale maxime și minime.</div>",formula_display:"∃x_max, x_min∈[a,b]: f(x_min)≤f(x)≤f(x_max)",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 60,140 C 100,60 140,150 180,90 C 210,45 250,70 280,110\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><line x1=\"60\" y1=\"170\" x2=\"60\" y2=\"140\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"280\" y1=\"170\" x2=\"280\" y2=\"110\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><circle cx=\"60\" cy=\"140\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"280\" cy=\"110\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"205\" cy=\"47\" r=\"5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><circle cx=\"140\" cy=\"150\" r=\"5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><line x1=\"205\" y1=\"47\" x2=\"205\" y2=\"170\" stroke=\"#c8922a\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"140\" y1=\"150\" x2=\"140\" y2=\"170\" stroke=\"#c8922a\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><text x=\"60\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">a</text><text x=\"280\" y=\"188\" text-anchor=\"middle\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">b</text><text x=\"205\" y=\"35\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">max</text><text x=\"140\" y=\"188\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">min</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă mergi pe o potecă între două garduri fixe (un drum închis, mărginit), iar înălțimea terenului se schimbă lin, fără salturi</span>, poteca are sigur un punct cel mai înalt și unul cel mai jos - nu poate „fugi” spre infinit sau doar să se apropie de un vârf fără să-l atingă niciodată.",intuitiv_nota:"Garantează existența soluțiilor la probleme de optimizare - stă la baza programării liniare și a multor algoritmi de optimizare folosiți în inginerie și economie.",exercitii:[{"q":"Găsește maximul și minimul lui f(x)=x² pe [-2,3].","pasi":["Evaluăm f la capete: f(-2)=4 și f(3)=9.","Căutăm puncte critice în interior: f'(x)=2x=0 dă x=0, unde f(0)=0.","Comparăm toate valorile candidate (0, 4, 9): minimul este 0 (în x=0), maximul este 9 (în x=3)."],"r":"✓ min=<strong>0</strong>, max=<strong>9</strong>"},{"q":"Weierstrass garantează un maxim pentru f(x)=sinx pe [0,b]. Care este cea mai mică valoare a lui b&gt;0 pentru care acest maxim atinge chiar valoarea 1?","pasi":["Maximul absolut al lui sinx (adică 1) se atinge la x=π/2.","Pentru ca acest punct să fie inclus în intervalul [0,b], e nevoie ca b≥π/2.","Cea mai mică valoare posibilă este b=π/2."],"r":"✓ b=<strong>π/2</strong>"},{"q":"Ce spune Weierstrass despre f pe intervalul degenerat [a,a] (un singur punct)?","pasi":["Intervalul [a,a] conține un singur punct, x=a.","Atât maximul cât și minimul lui f pe acest „interval” sunt automat f(a), pentru că nu există alt punct de comparat."],"r":"✓ max=min=<strong>f(a)</strong> - cazul trivial al unui singur punct"},{"q":"f(x)=1/x pe (0,1]. Se poate aplica teorema lui Weierstrass pentru a garanta un maxim?","pasi":["Intervalul (0,1] nu este închis (îi lipsește capătul 0), deci nu este compact.","Când x→0⁺, f(x)=1/x→∞, deci funcția nu este mărginită - nu are maxim finit.","Ipoteza de compactitate a intervalului lipsește, deci Weierstrass nu se aplică; și, într-adevăr, concluzia (existența unui maxim) e falsă aici."],"r":"✓ <strong>Nu se aplică</strong> - (0,1] nu e compact, iar f nu are maxim"},{"q":"Temperatura unui oraș se măsoară continuu de la ora 0 la ora 24 dintr-o zi (intervalul închis [0,24]). Arată că a existat cu certitudine un moment cu temperatura maximă a zilei.","pasi":["Fie T(t) temperatura la momentul t; T este continuă (temperatura nu sare brusc) pe intervalul închis și mărginit [0,24].","Ipotezele teoremei lui Weierstrass sunt îndeplinite: funcție continuă pe un compact.","Prin urmare T atinge efectiv un maxim (și un minim) undeva în [0,24] - a existat un moment exact cu temperatura cea mai ridicată a zilei."],"r":"✓ <strong>Da</strong>, garantat de teorema lui Weierstrass"}]};
CONTINUT_ANALIZA["limita-lui-e"]={definitie:"<div class=\"def-box\"><strong>Definiție:</strong> Constanta e este limita expresiei (1+1/n)ⁿ când n→∞, egală și cu suma ∑1/n! (adică 1+1+1/2!+1/3!+...).</div>",formula_display:"e = lim_{n→∞}(1+1/n)ⁿ = ∑_{n=0}^∞ 1/n! ≈ 2.71828…",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"55\" y1=\"55\" x2=\"290\" y2=\"55\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><path d=\"M 55,150 C 90,95 140,68 200,58 C 240,55 265,55 290,55\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><circle cx=\"55\" cy=\"150\" r=\"4\" fill=\"#4a1a7a\" stroke=\"#fff\" stroke-width=\"1.5\"/><circle cx=\"130\" cy=\"70\" r=\"4\" fill=\"#4a1a7a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"55\" y=\"188\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">n=1</text><text x=\"130\" y=\"188\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">n=10</text><text x=\"292\" y=\"46\" text-anchor=\"end\" font-size=\"11\" fill=\"#c8922a\" font-weight=\"600\">e≈2.71828</text><text x=\"42\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">(1+1/n)ⁿ</text><text x=\"300\" y=\"184\" text-anchor=\"end\" font-size=\"12\" fill=\"#555\" font-style=\"italic\">n</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă împarți o creștere într-un număr din ce în ce mai mare de pași mici, suma se apropie de un număr special</span>: e≈2.71828. Un leu la care dobânda de 100% se adaugă o singură dată devine 2 lei. Dacă aceeași dobândă se adaugă în pași tot mai mici și mai deși, banii cresc puțin mai mult - dar nu depășesc niciodată 2.718 lei.",intuitiv_nota:"e este irațional (Euler, 1744) și transcendent (Hermite, 1873). Apare în creșterea exponențială, distribuția normală și formula lui Euler.",exercitii:[{"q":"Calculează (1+1/10)¹⁰, cu patru zecimale.","pasi":["Înlocuim n=10 în formula (1+1/n)ⁿ și obținem (1.1)¹⁰.","Ridicăm 1.1 la puterea a zecea, calculând pas cu pas: (1.1)¹⁰≈2.5937.","Comparăm cu e≈2.71828: valoarea e apropiată, dar încă vizibil sub ea, pentru că n=10 nu e foarte mare."],"r":"✓ ≈<strong>2.5937</strong>"},{"q":"Pentru ce număr de compuneri n pe an obții aproximativ 2.613 lei, dintr-un leu depus cu dobândă anuală de 100%?","pasi":["Căutăm n astfel încât (1+1/n)ⁿ≈2.613.","Încercăm n=12, adică dobândă compusă lunar: (1+1/12)¹²≈2.613 - se potrivește.","Așadar compunerea de 12 ori pe an (lunar) dă acest rezultat."],"r":"✓ n=<strong>12</strong> (compunere lunară)"},{"q":"Ce se întâmplă pentru cel mai mic n posibil, n=1?","pasi":["Înlocuim n=1 în formulă: (1+1/1)¹=2¹.","Rezultatul este exact 2, mult sub e≈2.71828.","Acest caz arată că la n mic aproximarea e departe de e; abia pentru n foarte mare valoarea se apropie cu adevărat de e."],"r":"✓ Pentru n=1 valoarea este <strong>2</strong> - departe de e"},{"q":"Adevărat sau fals: șirul (1+1/n)ⁿ ajunge la un moment dat să depășească valoarea e, pentru un n suficient de mare.","pasi":["Șirul (1+1/n)ⁿ este strict crescător pe măsură ce n crește.","Dar este în același timp mărginit superior chiar de e - se apropie oricât de mult de e, fără să-l atingă sau să-l depășească vreodată, pentru niciun n finit."],"r":"✓ <strong>Fals</strong> - șirul rămâne mereu strict sub e"},{"q":"O bancă promite o dobândă anuală de 100%, compusă continuu (adăugată în pași infinit de mici, tot timpul anului). Cam câți lei ai avea la final, pornind de la 1 leu?","pasi":["Dobânda compusă de n ori pe an dă (1+1/n)ⁿ lei, pornind de la 1 leu depus.","Compunerea continuă înseamnă n→∞, adică exact limita din definiția lui e.","Suma finală este deci exact e lei."],"r":"✓ ≈<strong>2.71828 lei</strong> (exact e lei)"}]};
CONTINUT_ANALIZA["inegalitatea-cauchy-schwarz-integrala"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Pentru funcții integrabile f,g pe [a,b]: (∫ₐᵇ f·g dx)² ≤ (∫ₐᵇ f² dx)·(∫ₐᵇ g² dx), cu egalitate exact atunci când f și g sunt proporționale.</div>",formula_display:"(∫ f·g dx)² ≤ (∫ f² dx)·(∫ g² dx)",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"280\"><line x1=\"45\" y1=\"170\" x2=\"230\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><polygon points=\"230,170 218,165 218,175\" fill=\"#4a1a7a\"/><line x1=\"45\" y1=\"170\" x2=\"150\" y2=\"55\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><polygon points=\"150,55 156,67 141,64\" fill=\"#c8922a\"/><path d=\"M 85,170 A 40 40 0 0 0 96,149\" fill=\"none\" stroke=\"#999\" stroke-width=\"1\"/><line x1=\"150\" y1=\"55\" x2=\"150\" y2=\"170\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><circle cx=\"45\" cy=\"170\" r=\"3\" fill=\"#1a1510\"/><text x=\"236\" y=\"175\" font-size=\"12\" fill=\"#4a1a7a\" font-style=\"italic\" font-weight=\"600\">f</text><text x=\"156\" y=\"48\" font-size=\"12\" fill=\"#c8922a\" font-style=\"italic\" font-weight=\"600\">g</text><text x=\"98\" y=\"158\" font-size=\"11\" fill=\"#999\">θ</text><text x=\"150\" y=\"188\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">proiecția lui g pe f</text><text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">|⟨f,g⟩| ≤ ‖f‖·‖g‖ (egalitate la θ=0)</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă doi copii trag de aceeași sfoară, fiecare într-o direcție puțin diferită</span>, forța lor unită e cel mult egală cu produsul puterilor fiecăruia - și e cea mai mare doar atunci când trag exact în aceeași direcție. Cauchy-Schwarz spune același lucru despre funcții: „cât de mult se potrivesc” două funcții nu poate depăși niciodată produsul „mărimilor” lor.",intuitiv_nota:"Apare în principiul incertitudinii Heisenberg, teoria semnalelor și corelația statistică Pearson.",exercitii:[{"q":"Verifică inegalitatea pentru f(x)=x, g(x)=1 pe [0,1].","pasi":["Calculăm partea stângă: ∫₀¹x·1 dx=1/2, deci pătratul este (1/2)²=1/4.","Calculăm partea dreaptă: ∫₀¹x²dx=1/3 și ∫₀¹1²dx=1, deci produsul este 1/3·1=1/3.","Comparăm: 1/4≤1/3 - inegalitatea este verificată."],"r":"✓ <strong>1/4 ≤ 1/3</strong>, adevărat"},{"q":"Se știe că ∫₀¹f²dx=4 și ∫₀¹g²dx=9. Care este cea mai mare valoare posibilă a lui ∫₀¹f·g dx?","pasi":["Cauchy-Schwarz spune (∫fg)²≤(∫f²)(∫g²)=4·9=36.","De aici |∫fg|≤√36=6.","Acest maxim se atinge exact când f și g sunt proporționale, adică f=λg pentru o constantă λ&gt;0."],"r":"✓ Maximul posibil este <strong>6</strong>"},{"q":"Ce spune inegalitatea în cazul special g(x)=0 pe [a,b] (funcția identic nulă)?","pasi":["Partea stângă: ∫f·0 dx=0, deci pătratul este 0.","Partea dreaptă: ∫g²dx=∫0dx=0, deci întregul produs este (∫f²)·0=0.","Inegalitatea devine 0≤0 - o egalitate banală, adevărată pentru orice funcție f."],"r":"✓ <strong>Egalitate trivială</strong> 0=0, pentru orice f"},{"q":"Adevărat sau fals: egalitatea în Cauchy-Schwarz are loc doar atunci când una dintre funcții este identic nulă.","pasi":["Fals. Egalitatea are loc de fiecare dată când f și g sunt proporționale, f=λg, iar funcția nulă e doar cazul particular λ=0.","Exemplu: f(x)=x, g(x)=2x pe [0,1]. Calculăm ∫fg=∫2x²dx=2/3, deci (∫fg)²=4/9.","Calculăm și (∫f²)(∫g²)=(1/3)(4/3)=4/9 - identic, deci egalitate, deși nicio funcție nu e nulă."],"r":"✓ <strong>Fals</strong> - egalitate la orice pereche proporțională, nu doar la funcția nulă"},{"q":"Corelația dintre orele de somn și notele la teste, pentru un grup de elevi, nu poate depăși niciodată 1 în valoare absolută. De ce garantează Cauchy-Schwarz acest lucru?","pasi":["Coeficientul de corelație Pearson se scrie r=⟨f,g⟩/(‖f‖·‖g‖), unde f și g sunt abaterile datelor de la media lor.","Prin Cauchy-Schwarz, |⟨f,g⟩|≤‖f‖·‖g‖, deci raportul |r| este cel mult 1.","Așadar orice corelație statistică calculată astfel respectă automat |r|≤1, oricare ar fi datele."],"r":"✓ <strong>|r|≤1</strong> întotdeauna, garantat direct de Cauchy-Schwarz"}]};
CONTINUT_ANALIZA["formula-lui-euler-eipi"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Identitatea lui Euler e^(iπ)+1=0 leagă cele cinci constante fundamentale ale matematicii: e, i, π, 1 și 0.</div>",formula_display:"e^(iπ) + 1 = 0",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"280\"><circle cx=\"150\" cy=\"100\" r=\"70\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"70\" y1=\"100\" x2=\"230\" y2=\"100\" stroke=\"#999\" stroke-width=\"1\"/><line x1=\"150\" y1=\"170\" x2=\"150\" y2=\"30\" stroke=\"#999\" stroke-width=\"1\"/><path d=\"M 220,100 A 70 70 0 0 0 80,100\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/><circle cx=\"220\" cy=\"100\" r=\"4\" fill=\"#4a1a7a\" stroke=\"#fff\" stroke-width=\"1.5\"/><circle cx=\"80\" cy=\"100\" r=\"5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><line x1=\"150\" y1=\"100\" x2=\"80\" y2=\"100\" stroke=\"#c8922a\" stroke-width=\"1.5\"/><text x=\"228\" y=\"95\" font-size=\"11\" fill=\"#4a1a7a\">1 (θ=0)</text><text x=\"60\" y=\"95\" text-anchor=\"end\" font-size=\"11\" fill=\"#c8922a\" font-weight=\"600\">e^(iπ)=−1</text><text x=\"238\" y=\"103\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">Re</text><text x=\"155\" y=\"28\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">Im</text><text x=\"150\" y=\"188\" text-anchor=\"middle\" font-size=\"10\" fill=\"#999\">rotație cu unghiul π pe cercul unitate</text></svg>",intuitiv_text:"<span class=\"hl\">Numărul e^(ix) e ca un ac de ceas care se rotește pe un cerc de rază 1</span>: la unghiul 0 arată spre dreapta, spre 1. După o jumătate de rotație completă (unghiul π, adică 180°), acul ajunge exact în stânga, la −1. De aceea e^(iπ)+1=0: o rotație de 180° te aduce mereu în punctul opus.",intuitiv_nota:"Richard Feynman: „cea mai remarcabilă formulă din matematică”. Apare în mecanica cuantică și transformata Fourier.",exercitii:[{"q":"Calculează e^(iπ/2).","pasi":["Folosim formula e^(ix)=cosx+i·sinx, cu x=π/2.","Calculăm cos(π/2)=0 și sin(π/2)=1.","Rezultatul este 0+i·1=i."],"r":"✓ <strong>i</strong>"},{"q":"Pentru ce valoare a lui θ, cu 0≤θ&lt;2π, avem e^(iθ)=−i?","pasi":["Căutăm unghiul θ pentru care cosθ=0 și sinθ=−1.","Acest unghi este θ=3π/2 (adică 270°, trei sferturi de rotație).","Verificăm: cos(3π/2)=0, sin(3π/2)=−1, deci e^(i·3π/2)=0−i=−i. ✔"],"r":"✓ θ=<strong>3π/2</strong>"},{"q":"Ce se întâmplă în cazul special θ=0 (fără nicio rotație)?","pasi":["Înlocuim θ=0: cos0+i·sin0.","cos0=1 și sin0=0.","Rezultatul este 1+0=1 - punctul rămâne exact acolo unde a pornit, pe axa reală."],"r":"✓ <strong>1</strong> - fără rotație, rămânem în punctul de start"},{"q":"Adevărat sau fals: e^(i·10π) este „mult mai mare” decât e^(iπ), pentru că exponentul e mult mai mare.","pasi":["Fals. Modulul |e^(ix)|=√(cos²x+sin²x)=1 pentru orice x real, indiferent cât de mare e x.","e^(ix) rămâne mereu pe cercul unitate - se schimbă doar unghiul, adică rotația, nu „mărimea”.","10π înseamnă exact 5 rotații complete, deci e^(i·10π)=e^(i·0)=1, la fel de „mare” ca orice alt punct de pe cerc."],"r":"✓ <strong>Fals</strong> - modulul e mereu 1, indiferent de exponent"},{"q":"Un reflector fixat pe marginea unei roți de bicicletă are poziția z(t)=e^(iωt), cu viteza unghiulară ω=π rad/s. După cât timp ajunge reflectorul exact opus poziției de start?","pasi":["Poziția opusă începutului (adică −1) se atinge când unghiul total parcurs este exact π.","Unghiul parcurs după timpul t este ωt, deci punem condiția ωt=π.","Cu ω=π rad/s, obținem t=π/π=1 secundă."],"r":"✓ După <strong>1 secundă</strong>"}]};
CONTINUT_ANALIZA["seria-armonica"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Seria armonică ∑1/n diverge (suma crește nemărginit) deși termenii individuali tind la zero.</div>",formula_display:"∑_{n=1}^∞ 1/n = 1+1/2+1/3+… → ∞",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><rect x=\"50\" y=\"50\" width=\"28\" height=\"120\" fill=\"#4a1a7a\" fill-opacity=\"0.7\"/><rect x=\"83\" y=\"110\" width=\"28\" height=\"60\" fill=\"#4a1a7a\" fill-opacity=\"0.6\"/><rect x=\"116\" y=\"130\" width=\"28\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.5\"/><rect x=\"149\" y=\"140\" width=\"28\" height=\"30\" fill=\"#4a1a7a\" fill-opacity=\"0.45\"/><rect x=\"182\" y=\"146\" width=\"28\" height=\"24\" fill=\"#4a1a7a\" fill-opacity=\"0.4\"/><text x=\"64\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">1</text><text x=\"97\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">1/2</text><text x=\"130\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">1/3</text><text x=\"163\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">1/4</text><text x=\"196\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">1/5</text><text x=\"228\" y=\"163\" font-size=\"16\" fill=\"#999\">...</text><path d=\"M 250,163 C 270,150 285,110 290,55\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"5,3\"/><polygon points=\"290,55 282,66 296,65\" fill=\"#c8922a\"/><text x=\"292\" y=\"42\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c8922a\" font-weight=\"600\">∞</text><text x=\"165\" y=\"30\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">termenii→0, dar suma crește la infinit</text></svg>",intuitiv_text:"<span class=\"hl\">Fiecare pas e mai mic decât cel dinainte, dar dacă faci infinit de mulți pași, tot ajungi oricât de departe</span>. E ca și cum ai merge 1 metru, apoi jumătate de metru, apoi o treime de metru, tot mai puțin de fiecare dată - dar dacă nu te oprești niciodată din mers, ajungi oriunde vrei, doar că îți ia din ce în ce mai mult timp.",intuitiv_nota:"Nicole Oresme (~1350) a demonstrat divergența grupând termenii: (1/3+1/4)&gt;1/2, (1/5+...+1/8)&gt;1/2, și tot așa - un număr infinit de grupuri, fiecare mai mare decât 1/2. Seria crește extrem de lent: suma primilor 10⁴³ termeni depășește abia 100.",exercitii:[{"q":"Calculează suma primilor 4 termeni ai seriei armonice.","pasi":["Adunăm: 1+1/2+1/3+1/4.","Aducem la același numitor, 12: 12/12+6/12+4/12+3/12=25/12.","Rezultatul este 25/12≈2.083."],"r":"✓ ≈<strong>2.083</strong>"},{"q":"Care este cel mai mic număr de termeni N pentru care suma parțială H_N depășește 2?","pasi":["Calculăm H₃=1+1/2+1/3=11/6≈1.833, care este sub 2.","Calculăm H₄=1+1/2+1/3+1/4=25/12≈2.083, care depășește deja 2.","Deci N=4 este primul număr de termeni la care suma trece de 2."],"r":"✓ N=<strong>4</strong>"},{"q":"Suma primilor 1000 de termeni ai seriei armonice este o valoare finită sau infinită?","pasi":["Orice sumă cu un număr finit de termeni este automat finită, oricât de mulți termeni am aduna - aici valoarea e aproximativ 7.49.","Doar suma tuturor termenilor, la limită, cu n→∞, este cea care devine infinită.","Divergența seriei armonice e un fenomen „la infinit”, nu se vede la niciun pas finit, oricât de mare."],"r":"✓ <strong>Finită</strong> (≈7.49) - infinitul apare doar la limită, nu la un pas finit"},{"q":"Adevărat sau fals: din moment ce termenii 1/n tind la 0 când n→∞, seria armonică trebuie să conveargă.","pasi":["Fals. Tendința termenilor spre 0 este o condiție necesară pentru convergență, dar nu este suficientă.","Seria armonică este exact contraexemplul clasic: termenii tind la 0, dar suma tot diverge.","Gruparea lui Oresme arată exact de ce: chiar dacă termenii scad, grupurile de termeni consecutivi nu scad sub 1/2, deci suma crește la nesfârșit."],"r":"✓ <strong>Fals</strong> - termenii→0 e necesar, dar nu suficient pentru convergență"},{"q":"O bibliotecă adaugă cărți în fiecare lună: în luna n adaugă exact 1/n mii de cărți (luna 1: 1000, luna 2: 500, tot mai puține). Se va opri vreodată numărul total de cărți din creștere?","pasi":["Numărul total de cărți după n luni (în mii) este exact suma parțială a seriei armonice, H_n.","Chiar dacă adaosurile lunare devin oricât de mici, seria armonică diverge, deci H_n crește fără limită pe măsură ce trec lunile.","Așadar colecția bibliotecii crește nemărginit în timp, deși din ce în ce mai încet în fiecare lună."],"r":"✓ <strong>Nu</strong> - colecția crește nemărginit, doar din ce în ce mai încet"}]};
CONTINUT_ANALIZA["seria-lui-euler-pi-la-doi"]={definitie:"<div class=\"def-box\"><strong>Enunț (Problema Basel):</strong> Suma seriei pătratelor reciproce ale numerelor naturale este exact π²/6.</div>",formula_display:"∑_{n=1}^∞ 1/n² = π²/6 ≈ 1.6449",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><rect x=\"20\" y=\"80\" width=\"280\" height=\"40\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><rect x=\"20\" y=\"80\" width=\"170\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.65\"/><rect x=\"190\" y=\"80\" width=\"43\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.5\"/><rect x=\"233\" y=\"80\" width=\"19\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.38\"/><rect x=\"252\" y=\"80\" width=\"11\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.28\"/><rect x=\"263\" y=\"80\" width=\"37\" height=\"40\" fill=\"#c8922a\" fill-opacity=\"0.5\"/><text x=\"105\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"#fff\" font-weight=\"600\">1</text><text x=\"211\" y=\"105\" text-anchor=\"middle\" font-size=\"10\" fill=\"#fff\">1/4</text><text x=\"242\" y=\"103\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">1/9</text><text x=\"150\" y=\"140\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\">1+1/4+1/9+1/16+... → π²/6 ≈ 1.6449</text><text x=\"150\" y=\"60\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">infinit de termeni, sumă finită</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă aduni tot mai multe fracții tot mai mici - 1, apoi un sfert, apoi o noime, și tot așa la nesfârșit</span>, suma nu crește oricât de mult, ci se oprește exact la un număr legat de cercuri: π²/6≈1.6449. E surprinzător că π, numărul care apare la cercuri, apare și aici, unde nu se vede niciun cerc.",intuitiv_nota:"Pietro Mengoli a pus problema în 1650; nimeni nu a reușit să o rezolve timp de 90 de ani, până când Euler a comparat două expansiuni ale funcției sinus în 1734. Suma se notează ζ(2), un caz particular al funcției zeta Riemann.",exercitii:[{"q":"Calculează suma primilor 3 termeni ai seriei: 1+1/4+1/9.","pasi":["Aducem la același numitor, 36: 36/36+9/36+4/36.","Adunăm numărătorii: 36+9+4=49, deci suma este 49/36.","Rezultatul este 49/36≈1.361, încă vizibil sub limita π²/6≈1.6449 - mai rămân termeni de adăugat."],"r":"✓ ≈<strong>1.361</strong>"},{"q":"Știind că suma totală este π²/6≈1.6449 și suma primilor 3 termeni este ≈1.361, cât valorează suma tuturor termenilor rămași, de la n=4 până la infinit?","pasi":["Restul seriei este diferența dintre suma totală și suma parțială calculată: 1.6449−1.361.","Calculăm: 1.6449−1.361≈0.284.","Această valoare mică reprezintă exact ∑ (de la n=4 la infinit) 1/n², care converge repede pentru că termenii scad rapid."],"r":"✓ ≈<strong>0.284</strong>"},{"q":"Cât este suma ∑1/(2n)², adică doar termenii cu indice par din seria originală (1/4+1/16+1/36+...)?","pasi":["Scriem 1/(2n)²=1/(4n²)=(1/4)·(1/n²) - fiecare termen e a patra parte din termenul corespunzător al seriei originale.","Factorul 1/4 e comun tuturor termenilor, deci ∑1/(2n)²=(1/4)·∑1/n²=(1/4)·(π²/6).","Simplificăm: (1/4)·(π²/6)=π²/24."],"r":"✓ <strong>π²/24</strong>"},{"q":"Adevărat sau fals: seria alternantă ∑(−1)ⁿ⁺¹/n² (adică 1−1/4+1/9−1/16+...) are aceeași sumă ca seria cu toți termenii pozitivi, ∑1/n².","pasi":["Fals. Suma seriei alternante este π²/12, obținută scăzând de două ori suma termenilor pari din suma totală.","Suma seriei cu termeni pozitivi este π²/6, exact dublul valorii π²/12.","Cele două sume sunt legate, dar nu sunt egale - alternarea semnelor înjumătățește rezultatul."],"r":"✓ <strong>Fals</strong> - suma alternantă e π²/12, jumătate din π²/6"},{"q":"Probabilitatea ca două numere întregi alese la întâmplare să fie prime între ele (fără niciun factor comun) este exact 6/π². Ce legătură are acest fapt cu seria lui Euler?","pasi":["Numărul 6/π² este chiar inversul sumei seriei lui Euler, pentru că π²/6=∑1/n², deci 6/π²=1/∑(1/n²).","Teoria numerelor arată că această probabilitate se calculează dintr-un produs peste toate numerele prime, care se dovedește egal exact cu inversul acestei sume.","Așa apare, surprinzător, seria lui Euler într-o problemă de teoria numerelor, complet diferită de contextul ei inițial."],"r":"✓ Probabilitatea este <strong>6/π²≈0.608</strong>, legată direct de seria lui Euler"}]};
CONTINUT_ANALIZA["teorema-lui-fubini"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Dacă f:[a,b]×[c,d]→ℝ este integrabilă, integrala dublă se poate calcula iterând integralele simple în orice ordine, cu același rezultat.</div>",formula_display:"∬f(x,y)dA = ∫ₐᵇ(∫_c^d f dy)dx = ∫_c^d(∫ₐᵇ f dx)dy",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><rect x=\"30\" y=\"30\" width=\"100\" height=\"120\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><rect x=\"70\" y=\"30\" width=\"18\" height=\"120\" fill=\"#4a1a7a\" fill-opacity=\"0.5\"/><rect x=\"190\" y=\"30\" width=\"100\" height=\"120\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><rect x=\"190\" y=\"78\" width=\"100\" height=\"18\" fill=\"#c8922a\" fill-opacity=\"0.5\"/><text x=\"158\" y=\"98\" text-anchor=\"middle\" font-size=\"20\" fill=\"#555\">=</text><text x=\"80\" y=\"168\" text-anchor=\"middle\" font-size=\"10\" fill=\"#4a1a7a\" font-weight=\"600\">întâi pe y, apoi pe x</text><text x=\"240\" y=\"168\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">întâi pe x, apoi pe y</text><text x=\"22\" y=\"34\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">c</text><text x=\"22\" y=\"154\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">a</text><text x=\"130\" y=\"154\" text-anchor=\"end\" font-size=\"10\" fill=\"#555\">b</text><text x=\"160\" y=\"188\" text-anchor=\"middle\" font-size=\"10\" fill=\"#999\">același rezultat, indiferent de ordine</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă numeri o cutie cu ciocolate așezate în rânduri și coloane, obții același total indiferent dacă numeri mai întâi pe rânduri sau mai întâi pe coloane</span>. Fubini spune același lucru despre „numărarea” unei suprafețe: nu contează ordinea de adunare, rezultatul e mereu identic.",intuitiv_nota:"Guido Fubini a precizat condițiile exacte în 1907. Este baza calculului volumelor, probabilității bivariate și geometriei diferențiale.",exercitii:[{"q":"Calculează ∬xy dA pe dreptunghiul [0,1]×[0,2], integrând în ambele ordini, ca să verifici că rezultatul e același.","pasi":["Întâi pe y, apoi pe x: ∫₀²xy dy=x·(y²/2 între 0 și 2)=2x, apoi ∫₀¹2x dx=1.","Acum pe cealaltă ordine, întâi pe x, apoi pe y: ∫₀¹xy dx=y·(x²/2 între 0 și 1)=y/2, apoi ∫₀²(y/2)dy=1.","Ambele ordini dau exact 1 - confirmă Fubini pentru acest exemplu."],"r":"✓ <strong>1</strong>, în ambele ordini"},{"q":"O funcție constantă f(x,y)=k pe dreptunghiul [0,3]×[0,4] are ∬f dA=12. Cât este k?","pasi":["Pentru o constantă k, integrala dublă este k înmulțit cu aria dreptunghiului: ∬k dA=k·(3×4)=12k.","Punem condiția din enunț: 12k=12.","Rezultă k=1."],"r":"✓ k=<strong>1</strong>"},{"q":"Cât este ∬f dA pe domeniul degenerat [2,2]×[0,5] (un „dreptunghi” cu lățime zero pe direcția x)?","pasi":["Intervalul pe x are lungime 0 (de la 2 la 2), oricare ar fi f și oricare ordine de integrare am alege.","Integrarea pe un interval de lungime 0 dă întotdeauna 0, ca la integrala simplă.","Deci întreaga integrală dublă este 0, indiferent de funcția f."],"r":"✓ <strong>0</strong> - domeniu degenerat pe direcția x"},{"q":"Adevărat sau fals: se poate schimba întotdeauna ordinea de integrare într-o integrală dublă, indiferent de funcția f.","pasi":["Fals. Teorema lui Fubini cere ca f să fie integrabilă (de exemplu, ∬|f|dA finită) pentru ca schimbarea ordinii să fie valabilă.","Există funcții pentru care cele două ordini de integrare dau rezultate diferite - exemplul clasic este f(x,y)=(x²−y²)/(x²+y²)² pe [0,1]×[0,1].","Acolo tocmai pentru că ipoteza de integrabilitate absolută nu e satisfăcută, concluzia Fubini nu mai este garantată."],"r":"✓ <strong>Fals</strong> - ipoteza de integrabilitate a lui f este esențială"},{"q":"O placă dreptunghiulară de metal, de dimensiuni [0,1]×[0,π], are temperatura descrisă de T(x,y)=eˣ·sinY. Calculează „temperatura totală acumulată” pe toată placa (integrala dublă a lui T).","pasi":["Cum T(x,y) se scrie ca produs eˣ·sinY, Fubini permite separarea integralei duble în produsul a două integrale simple.","Calculăm fiecare parte: ∫₀¹eˣdx=e−1≈1.718, și ∫₀^π sinY dY=2.","Înmulțim cele două rezultate: (e−1)·2≈3.437."],"r":"✓ <strong>2(e−1)≈3.437</strong>"}]};
CONTINUT_ANALIZA["teorema-punctului-fix-banach"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice contracție f pe un spațiu metric complet (X,d) are un unic punct fix x*, obținut ca limita șirului xₙ₊₁=f(xₙ), pornind din orice punct x₀.</div>",formula_display:"∃!x*: f(x*)=x*; d(f(x),f(y))≤q·d(x,y), q&lt;1",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"280\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"270\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"170\" x2=\"200\" y2=\"10\" stroke=\"#999\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><path d=\"M 40,130 L 200,55\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><polyline points=\"55,170 55,124 124,124 124,92 155,92 155,76 170,76\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.5\"/><circle cx=\"140\" cy=\"83\" r=\"4.5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"55\" y=\"185\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">x₀</text><text x=\"140\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">x*</text><text x=\"205\" y=\"12\" font-size=\"10\" fill=\"#999\">y=x</text><text x=\"205\" y=\"52\" font-size=\"10\" fill=\"#4a1a7a\">f(x)</text><text x=\"150\" y=\"190\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">iterațiile xₙ₊₁=f(xₙ) converg spre x*</text></svg>",intuitiv_text:"<span class=\"hl\">Imaginează-ți un joc în care, la fiecare pas, te apropii de o comoară ascunsă la cel puțin jumătate din distanța rămasă</span>. Oriunde ai porni, după destui pași ajungi oricât de aproape vrei de comoară - și există un singur loc unde ea se poate afla, oricare ar fi drumul de pornire.",intuitiv_nota:"Stefan Banach a demonstrat teorema în 1922. Este baza multor algoritmi iterativi din calculatoare și a existenței soluțiilor pentru ecuații diferențiale.",exercitii:[{"q":"f(x)=cosx. Aproximează punctul fix prin iterații repetate, pornind de la x₀=0.","pasi":["Calculăm primii termeni ai șirului xₙ₊₁=cos(xₙ): x₀=0, x₁=cos(0)=1, x₂=cos(1)≈0.540, x₃=cos(0.540)≈0.858.","Continuând iterațiile, valorile oscilează tot mai puțin, apropiindu-se de soluția ecuației x=cosx.","După suficiente iterații, șirul se stabilizează la x*≈0.739."],"r":"✓ x*≈<strong>0.739</strong>"},{"q":"Iterația xₙ₊₁=xₙ/k+2 converge, indiferent de x₀, la punctul fix x*=5. Află valoarea lui k.","pasi":["La limită, punctul fix satisface ecuația x*=x*/k+2, deci 5=5/k+2.","Rezolvăm pentru 5/k: 5/k=5−2=3.","Rezultă k=5/3. Verificăm contracția: constanta este |1/k|=3/5=0.6&lt;1, deci într-adevăr converge."],"r":"✓ k=<strong>5/3</strong>"},{"q":"f(x)=7 (funcție constantă) pentru orice x real. Care este punctul fix și în câți pași se ajunge exact la el?","pasi":["Pentru orice x, f(x)=7, deci punctul fix trebuie să satisfacă x*=f(x*)=7, adică x*=7.","Distanța dintre oricare două imagini este d(f(x),f(y))=|7−7|=0=0·d(x,y), deci constanta de contracție este q=0 - cea mai puternică contracție posibilă.","Practic, orice iterație ajunge direct la punctul fix după un singur pas: x₁=f(x₀)=7, indiferent de x₀."],"r":"✓ x*=<strong>7</strong>, atins într-un <strong>singur pas</strong>"},{"q":"f(x)=x+1 pe ℝ. Este f o contracție? Are punct fix?","pasi":["Calculăm d(f(x),f(y))=|(x+1)−(y+1)|=|x−y|, deci constanta este q=1, nu strict subunitară.","Fără q&lt;1, f nu este o contracție - distanța dintre puncte nu se micșorează niciodată la aplicarea lui f.","Într-adevăr, ecuația x=f(x)=x+1 nu are nicio soluție, deci f nu are niciun punct fix, exact cum sugerează lipsa ipotezei."],"r":"✓ <strong>Nu e contracție</strong> și <strong>nu are punct fix</strong>"},{"q":"Prețul unui produs se ajustează zilnic după regula pₙ₊₁=0.5·pₙ+50 (prețul de mâine depinde de cel de azi). La ce preț se stabilizează el pe termen lung, indiferent de prețul inițial?","pasi":["La echilibru, prețul limită satisface p*=0.5·p*+50.","Rezolvăm: p*−0.5p*=50, deci 0.5·p*=50.","Rezultă p*=100. Constanta de contracție este 0.5&lt;1, deci Banach garantează convergența la acest preț unic, indiferent de prețul de pornire."],"r":"✓ Prețul se stabilizează la <strong>100 lei</strong>"}]};
CONTINUT_ANALIZA["formula-de-moivre"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> (cosθ+i·sinθ)ⁿ=cos(nθ)+i·sin(nθ), pentru orice θ real și orice n întreg.</div>",formula_display:"(cosθ + i·sinθ)ⁿ = cos(nθ) + i·sin(nθ)",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"280\"><circle cx=\"150\" cy=\"100\" r=\"70\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"75\" y1=\"100\" x2=\"225\" y2=\"100\" stroke=\"#999\" stroke-width=\"1\"/><line x1=\"150\" y1=\"170\" x2=\"150\" y2=\"30\" stroke=\"#999\" stroke-width=\"1\"/><line x1=\"150\" y1=\"100\" x2=\"210\" y2=\"65\" stroke=\"#4a1a7a\" stroke-width=\"2\"/><line x1=\"150\" y1=\"100\" x2=\"112\" y2=\"34\" stroke=\"#c8922a\" stroke-width=\"2\"/><path d=\"M 220,100 A 70 70 0 0 0 210,65\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 220,100 A 70 70 0 0 0 112,34\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><circle cx=\"210\" cy=\"65\" r=\"4\" fill=\"#4a1a7a\" stroke=\"#fff\" stroke-width=\"1.5\"/><circle cx=\"112\" cy=\"34\" r=\"4.5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"216\" y=\"60\" font-size=\"11\" fill=\"#4a1a7a\" font-weight=\"600\">θ</text><text x=\"100\" y=\"30\" font-size=\"11\" fill=\"#c8922a\" font-weight=\"600\">nθ</text><text x=\"215\" y=\"80\" font-size=\"10\" fill=\"#4a1a7a\">z=cosθ+i·sinθ</text><text x=\"108\" y=\"20\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">zⁿ=cos(nθ)+i·sin(nθ)</text><text x=\"150\" y=\"188\" text-anchor=\"middle\" font-size=\"10\" fill=\"#999\">n rotații de unghi θ = o rotație de unghi nθ</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă te rotești de mai multe ori cu același unghi, la final ești rotit cu suma tuturor unghiurilor</span>. De Moivre spune că, pentru numerele de pe cercul unitate, a le înmulți de n ori între ele înseamnă exact a te roti de n ori cu același unghi - adică o singură rotație, de n ori mai mare.",intuitiv_nota:"Abraham de Moivre a publicat formula în 1722. Este baza formulelor trigonometrice pentru unghiuri multiple și a transformatelor Fourier discrete.",exercitii:[{"q":"Calculează (cos30°+i·sin30°)⁶.","pasi":["Aplicăm De Moivre cu n=6 și θ=30°: rezultatul este cos(6·30°)+i·sin(6·30°)=cos180°+i·sin180°.","Calculăm cos180°=−1 și sin180°=0.","Rezultatul este −1+0i=−1."],"r":"✓ <strong>−1</strong>"},{"q":"Găsește toate numerele complexe z cu z³=1 (rădăcinile cubice ale unității), folosind De Moivre.","pasi":["Scriem 1=cos(360°k)+i·sin(360°k) pentru orice întreg k, adăugând un tur complet fără să schimbăm valoarea.","Căutăm z=cosφ+i·sinφ cu z³=cos(3φ)+i·sin(3φ)=1, deci 3φ=360°k, adică φ=120°k.","Pentru k=0,1,2 obținem cele trei rădăcini distincte: z=1 (φ=0°), z=cos120°+i·sin120°, și z=cos240°+i·sin240°; pentru k=3 s-ar repeta prima rădăcină."],"r":"✓ <strong>1, cos120°+i·sin120°, cos240°+i·sin240°</strong>"},{"q":"Cât este (cosθ+i·sinθ)⁰, pentru orice unghi θ?","pasi":["Aplicăm De Moivre cu n=0: rezultatul este cos(0·θ)+i·sin(0·θ)=cos0°+i·sin0°.","Calculăm cos0°=1 și sin0°=0, deci rezultatul este exact 1.","Asta e valabil indiferent de θ - puterea zero a oricărui număr de pe cercul unitate este 1."],"r":"✓ <strong>1</strong>, pentru orice θ"},{"q":"Adevărat sau fals: formula lui De Moivre este valabilă doar pentru n număr natural pozitiv.","pasi":["Fals - formula (cosθ+i·sinθ)ⁿ=cos(nθ)+i·sin(nθ) este valabilă pentru orice n întreg, inclusiv 0 și numere negative.","Verificăm pentru n=−1: formula dă cos(−θ)+i·sin(−θ)=cosθ−i·sinθ.","Acesta este exact inversul lui cosθ+i·sinθ pe cercul unitate, confirmat prin calcul direct: (cosθ+isinθ)(cosθ−isinθ)=cos²θ+sin²θ=1."],"r":"✓ <strong>Fals</strong> - formula e valabilă pentru orice n întreg"},{"q":"O gondolă a unei roți panoramice pornește la unghiul 0° și se rotește cu exact 50° la fiecare oprire. Ce unghi total are gondola după 4 opriri, folosind De Moivre?","pasi":["Fiecare oprire înmulțește poziția (un punct pe cercul unitate) cu factorul cos50°+i·sin50°.","După 4 opriri, prin De Moivre, poziția totală este (cos50°+i·sin50°)⁴=cos(4·50°)+i·sin(4·50°)=cos200°+i·sin200°.","Numeric, cos200°≈−0.940 și sin200°≈−0.342, deci gondola ajunge la unghiul total de 200° față de poziția de pornire."],"r":"✓ Unghiul total este <strong>200°</strong> (poziția ≈−0.940−0.342i)"}]};
CONTINUT_ANALIZA["criteriul-lui-cauchy-condensare"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie (aₙ) un șir descrescător de numere pozitive. Atunci seria ∑aₙ converge dacă și numai dacă seria condensată ∑2ⁿa₂ₙ converge.</div>",formula_display:"∑aₙ converge ↔ ∑2ⁿa₂ₙ converge",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"30\" y1=\"150\" x2=\"300\" y2=\"150\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><rect x=\"40\" y=\"60\" width=\"14\" height=\"90\" fill=\"#4a1a7a\" fill-opacity=\"0.7\"/><rect x=\"58\" y=\"80\" width=\"14\" height=\"70\" fill=\"#4a1a7a\" fill-opacity=\"0.6\"/><rect x=\"76\" y=\"90\" width=\"14\" height=\"60\" fill=\"#4a1a7a\" fill-opacity=\"0.55\"/><rect x=\"94\" y=\"100\" width=\"14\" height=\"50\" fill=\"#4a1a7a\" fill-opacity=\"0.5\"/><rect x=\"112\" y=\"106\" width=\"14\" height=\"44\" fill=\"#4a1a7a\" fill-opacity=\"0.46\"/><rect x=\"130\" y=\"110\" width=\"14\" height=\"40\" fill=\"#4a1a7a\" fill-opacity=\"0.44\"/><rect x=\"148\" y=\"113\" width=\"14\" height=\"37\" fill=\"#4a1a7a\" fill-opacity=\"0.42\"/><rect x=\"166\" y=\"116\" width=\"14\" height=\"34\" fill=\"#4a1a7a\" fill-opacity=\"0.4\"/><text x=\"195\" y=\"140\" font-size=\"14\" fill=\"#999\">...</text><path d=\"M 40,160 L 54,160\" stroke=\"#c8922a\" stroke-width=\"2\"/><path d=\"M 58,160 L 90,160\" stroke=\"#c8922a\" stroke-width=\"2\"/><path d=\"M 94,160 L 180,160\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"47\" y=\"175\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">2⁰=1</text><text x=\"74\" y=\"175\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">2¹=2</text><text x=\"137\" y=\"175\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">2²=4</text><text x=\"150\" y=\"30\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">grupăm termenii în blocuri care se dublează</text><text x=\"150\" y=\"190\" text-anchor=\"middle\" font-size=\"10\" fill=\"#999\">suma blocului ~ 2ⁿ·a₂ₙ</text></svg>",intuitiv_text:"<span class=\"hl\">Grupează termenii în „pachete” a căror mărime se dublează mereu: primul pachet are 1 termen, al doilea are 2, al treilea are 4, și tot așa</span>. Fiindcă șirul e descrescător, toți termenii dintr-un pachet sunt cam la fel de mari ca primul din pachet - deci suma pachetului seamănă cu (mărimea pachetului) ori (primul termen). Verificând doar aceste pachete reprezentative, aflăm dacă toată suma e finită sau infinită, fără să aduni fiecare termen în parte.",intuitiv_nota:"Cauchy a introdus acest criteriu pentru a decide rapid convergența seriilor de tip ∑1/(n(ln n)^p), acolo unde criteriul raportului și al rădăcinii eșuează (dau ambele L=1). Este generalizarea trucului de grupare al lui Oresme, folosit la seria armonică.",exercitii:[{"q":"∑1/n² - aplică criteriul de condensare.","pasi":["Verificăm ipoteza: aₙ=1/n² este pozitiv și descrescător.","Formăm seria condensată: 2ⁿa₂ₙ=2ⁿ/(2ⁿ)²=2ⁿ/2²ⁿ=2⁻ⁿ.","Seria ∑2⁻ⁿ este geometrică cu rația 1/2&lt;1, deci converge - prin criteriu, și ∑1/n² converge."],"r":"✓ <strong>Convergentă</strong>"},{"q":"∑1/n (seria armonică) - cazul limită dintre convergență și divergență printre seriile ∑1/nᵖ.","pasi":["Verificăm ipoteza: aₙ=1/n este pozitiv și descrescător.","Formăm seria condensată: 2ⁿa₂ₙ=2ⁿ·(1/2ⁿ)=1, adică un termen constant, egal cu 1, pentru orice n.","O sumă de infinit de termeni egali cu 1 diverge evident, deci și seria armonică diverge - exact cazul-limită p=1 dintre p&gt;1 (converge) și p≤1 (diverge)."],"r":"✓ <strong>Divergentă</strong> - cazul-limită p=1"},{"q":"Se știe că seria condensată a unei serii ∑aₙ, cu (aₙ) pozitiv și descrescător, este exact ∑1/n². Ce spune criteriul de condensare despre seria originală ∑aₙ?","pasi":["Criteriul afirmă o echivalență: ∑aₙ converge dacă și numai dacă seria condensată ∑2ⁿa₂ₙ converge.","Seria condensată dată, ∑1/n², este convergentă (este chiar suma lui Euler, π²/6).","Prin echivalență, rezultă direct că și seria originală ∑aₙ converge - fără să cunoaștem nici măcar formula exactă a lui aₙ."],"r":"✓ <strong>∑aₙ converge</strong>, dedus direct din echivalență"},{"q":"Adevărat sau fals: criteriul de condensare se poate aplica oricărui șir de termeni pozitivi (aₙ), indiferent dacă este descrescător sau nu.","pasi":["Fals - ipoteza de monotonie (aₙ descrescător) este esențială în demonstrație.","Fără ea, termenii dintr-un bloc de la 2ⁿ la 2ⁿ⁺¹−1 nu mai pot fi încadrați între a₂ₙ și a₂ₙ₊₁, deci suma blocului nu mai poate fi comparată sigur cu 2ⁿa₂ₙ.","Fără monotonie, seria condensată și seria originală pot avea comportări complet diferite, deci criteriul nu se mai aplică."],"r":"✓ <strong>Fals</strong> - monotonia lui (aₙ) este o ipoteză obligatorie"},{"q":"Populația unui oraș crește cu aₙ=1/(n·(ln n)²) mii de locuitori în anul n (n≥2), o rată tot mai mică în timp. Va crește orașul nemărginit, sau populația totală adăugată se va stabiliza?","pasi":["Aplicăm criteriul de condensare: 2ⁿa₂ₙ=2ⁿ/(2ⁿ(n·ln2)²)=1/((ln2)²·n²).","Seria ∑1/((ln2)²·n²) este, până la o constantă, seria ∑1/n², care converge.","Prin criteriu, rezultă că și ∑aₙ converge - populația totală adăugată de-a lungul timpului se stabilizează la o valoare finită, în loc să crească nemărginit."],"r":"✓ <strong>Se stabilizează</strong> - suma tuturor creșterilor e finită"}]};
CONTINUT_ANALIZA["teorema-stolz-cesaro"]={definitie:"<div class=\"def-box\"><strong>Enunț (cazul ∞/∞):</strong> Fie (bₙ) strict crescător cu bₙ→∞. Dacă există lim (aₙ₊₁−aₙ)/(bₙ₊₁−bₙ)=L (finită sau infinită), atunci există și lim aₙ/bₙ=L.</div>",formula_display:"lim aₙ/bₙ = lim (aₙ₊₁−aₙ)/(bₙ₊₁−bₙ)",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><polyline points=\"50,160 80,145 110,122 140,92 170,55 200,10\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><polyline points=\"50,165 80,158 110,148 140,133 170,112 200,82\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"140\" cy=\"92\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"170\" cy=\"55\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"140\" cy=\"133\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"170\" cy=\"112\" r=\"3.5\" fill=\"#c8922a\"/><line x1=\"140\" y1=\"92\" x2=\"170\" y2=\"92\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><line x1=\"170\" y1=\"55\" x2=\"170\" y2=\"92\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><line x1=\"140\" y1=\"133\" x2=\"170\" y2=\"133\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><line x1=\"170\" y1=\"112\" x2=\"170\" y2=\"133\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><text x=\"255\" y=\"20\" font-size=\"11\" fill=\"#4a1a7a\" font-style=\"italic\">aₙ</text><text x=\"255\" y=\"88\" font-size=\"11\" fill=\"#c8922a\" font-style=\"italic\">bₙ</text><text x=\"155\" y=\"85\" text-anchor=\"middle\" font-size=\"9\" fill=\"#4a1a7a\">Δa</text><text x=\"155\" y=\"145\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">Δb</text><text x=\"150\" y=\"188\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">Δaₙ/Δbₙ → L ⟹ aₙ/bₙ → L</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă la fiecare pas doi copii cresc cam în același ritm - unul adaugă mereu cam cât adaugă și celălalt - atunci, per total, cei doi ajung tot cam la fel de „mari”</span>. Stolz-Cesàro spune exact asta: dacă pașii (diferențele) a două șiruri au un raport care se apropie de un număr L, atunci și șirurile în sine ajung să aibă același raport L.",intuitiv_nota:"Otto Stolz (1885) și, independent, Ernesto Cesàro au formulat criteriul. Este esențial la limite cu sume de tipul (1+2+...+n)/n² sau la medii Cesàro, acolo unde regula lui L'Hôpital nu se aplică direct, neexistând o funcție continuă de derivat.",exercitii:[{"q":"Calculează lim (1+2+...+n)/n².","pasi":["Notăm aₙ=1+2+...+n și bₙ=n²; (bₙ) e strict crescător și →∞.","Calculăm diferențele: aₙ₊₁−aₙ=n+1, iar bₙ₊₁−bₙ=(n+1)²−n²=2n+1.","Limita raportului diferențelor este lim (n+1)/(2n+1)=1/2, deci prin Stolz-Cesàro, lim aₙ/bₙ=1/2."],"r":"✓ <strong>1/2</strong>"},{"q":"Pentru ce valoare a constantei c avem lim (c+2c+3c+...+nc)/n² = 6, folosind Stolz-Cesàro?","pasi":["Notăm aₙ=c+2c+...+nc=c·(1+2+...+n) și bₙ=n².","Diferențele: aₙ₊₁−aₙ=c·(n+1), iar bₙ₊₁−bₙ=2n+1; raportul lor tinde la lim c(n+1)/(2n+1)=c/2.","Teorema garantează atunci lim aₙ/bₙ=c/2; punem condiția c/2=6, deci c=12."],"r":"✓ c=<strong>12</strong>"},{"q":"Verifică teorema în cazul simplu aₙ=5n, bₙ=n (progresie aritmetică simplă).","pasi":["Diferențele sunt aₙ₊₁−aₙ=5(n+1)−5n=5, respectiv bₙ₊₁−bₙ=(n+1)−n=1, deci raportul lor este constant, 5/1=5.","Prin Stolz-Cesàro, rezultă lim aₙ/bₙ=5.","Verificăm direct: aₙ/bₙ=5n/n=5 pentru orice n - același rezultat, confirmând teorema în acest caz trivial."],"r":"✓ <strong>5</strong>, confirmat și prin calcul direct"},{"q":"Adevărat sau fals: dacă limita aₙ/bₙ există, atunci obligatoriu există și limita raportului diferențelor (aₙ₊₁−aₙ)/(bₙ₊₁−bₙ) - adică teorema Stolz-Cesàro s-ar putea „inversa”.","pasi":["Fals. Contraexemplu: aₙ=(−1)ⁿ, bₙ=n (strict crescător, →∞).","Limita aₙ/bₙ=(−1)ⁿ/n există și este 0.","Dar raportul diferențelor este (aₙ₊₁−aₙ)/(bₙ₊₁−bₙ)=(−1)ⁿ·(−2)/1, care oscilează la nesfârșit între −2 și 2, fără limită."],"r":"✓ <strong>Fals</strong> - limita aₙ/bₙ poate exista fără ca raportul diferențelor să aibă limită"},{"q":"Notele obținute de un elev la teste succesive se apropie tot mai mult de 8 (nota la testul n, xₙ, satisface xₙ→8). Dacă Sₙ=x₁+x₂+...+xₙ, ce spune Stolz-Cesàro despre media pe termen lung, lim Sₙ/n?","pasi":["Notăm aₙ=Sₙ și bₙ=n. Diferența aₙ₊₁−aₙ=Sₙ₊₁−Sₙ=xₙ₊₁, adică exact nota la testul următor.","Diferența bₙ₊₁−bₙ=1, deci raportul (aₙ₊₁−aₙ)/(bₙ₊₁−bₙ)=xₙ₊₁, care tinde la 8 prin ipoteză.","Aplicând Stolz-Cesàro, rezultă lim Sₙ/n=8: media notelor pe termen lung tinde spre aceeași valoare spre care tind notele individuale."],"r":"✓ Media pe termen lung tinde spre <strong>8</strong>"}]};
CONTINUT_ANALIZA["teorema-lui-abel-serii"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie f(x)=∑aₙxⁿ o serie de puteri cu raza de convergență R=1. Dacă seria numerică ∑aₙ converge, atunci f este continuă la stânga în x=1, adică lim_{x→1⁻}f(x)=∑aₙ.</div>",formula_display:"lim_{x→1⁻} ∑aₙxⁿ = ∑aₙ (dacă ∑aₙ converge)",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 60,150 C 120,130 180,90 260,55\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><line x1=\"260\" y1=\"170\" x2=\"260\" y2=\"20\" stroke=\"#999\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><circle cx=\"260\" cy=\"55\" r=\"5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"260\" y=\"188\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\" font-weight=\"600\">x=1</text><text x=\"60\" y=\"188\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">x=0</text><text x=\"270\" y=\"50\" font-size=\"11\" fill=\"#c8922a\" font-weight=\"600\">S=∑aₙ</text><text x=\"150\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" fill=\"#4a1a7a\" font-style=\"italic\">f(x)=∑aₙxⁿ</text><text x=\"150\" y=\"188\" text-anchor=\"middle\" font-size=\"10\" fill=\"#999\">dacă ∑aₙ converge, f ajunge continuu până la x=1</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă mergi pe un drum care se apropie tot mai mult de marginea unei hărți, iar drumul chiar ajunge acolo, fără să se rupă brusc</span>, punctul de sosire de pe margine e exact acolo unde te-ai aștepta, continuând drumul din priviri. Așa e și cu seria de puteri: dacă suma numerelor de la capătul intervalului chiar există, funcția „ajunge” acolo lin, fără sărituri.",intuitiv_nota:"Abel a folosit teorema pentru a justifica riguros sume precum 1−1/2+1/3−1/4+...=ln2, obținute anterior prin manipulări formale ale seriilor de puteri. Teorema NU se poate inversa: existența limitei lui f nu implică faptul că seria numerică converge.",exercitii:[{"q":"Calculează ∑(−1)ⁿ⁺¹/n folosind f(x)=∑(−1)ⁿ⁺¹xⁿ/n=ln(1+x).","pasi":["Verificăm ipoteza: seria ∑(−1)ⁿ⁺¹/n converge, prin criteriul lui Leibniz (termeni pozitivi, descrescători, spre 0).","Pentru |x|&lt;1, suma seriei de puteri este cunoscută: f(x)=ln(1+x).","Prin Abel, putem trece la limită și în x=1: lim_{x→1⁻}ln(1+x)=ln2, deci exact aceasta e suma seriei numerice."],"r":"✓ <strong>ln2</strong>"},{"q":"Coeficienții unei serii de puteri sunt aₙ=1/(n(n+1)). Fără să calculezi formula explicită a lui f(x)=∑aₙxⁿ, află lim_{x→1⁻}f(x) folosind Abel.","pasi":["Mai întâi calculăm ∑aₙ direct, ca sumă numerică: 1/(n(n+1))=1/n−1/(n+1) (descompunere telescopică).","Suma parțială telescopează: (1−1/2)+(1/2−1/3)+...+(1/N−1/(N+1))=1−1/(N+1)→1 când N→∞, deci ∑aₙ=1.","Fiindcă ∑aₙ converge la 1, Abel garantează direct lim_{x→1⁻}f(x)=1, fără să fi avut nevoie de formula explicită a lui f."],"r":"✓ <strong>1</strong>"},{"q":"Se poate aplica Abel lui f(x)=∑xⁿ=1/(1−x) în x=1?","pasi":["Aici aₙ=1 pentru orice n, deci aₙ nu tinde la 0, iar ∑1 diverge - ipoteza teoremei (convergența lui ∑aₙ) nu este satisfăcută.","Abel nu se aplică, deci teorema nu garantează nimic despre limita la stânga în x=1.","Consecvent, calculând direct: lim_{x→1⁻}1/(1−x)=+∞, deci nici concluzia (o limită finită) nu este adevărată aici."],"r":"✓ <strong>Nu se aplică</strong>; și, într-adevăr, limita este +∞"},{"q":"Fie aₙ=(−1)ⁿ și f(x)=∑(−1)ⁿxⁿ=1/(1+x). Ce arată cazul x→1⁻ despre reciproca teoremei lui Abel?","pasi":["Calculăm limita la stânga: lim_{x→1⁻}1/(1+x)=1/2, care există și este finită.","Dar seria numerică ∑(−1)ⁿ oscilează între −1 și 0 (sumele parțiale nu se stabilizează), deci nu converge.","Așadar limita lui f poate exista chiar și atunci când seria numerică ∑aₙ nu converge - reciproca teoremei lui Abel este falsă."],"r":"✓ <strong>Reciproca e falsă</strong> - limita lui f poate exista fără ca ∑aₙ să conveargă"},{"q":"Un program de calculator estimează ln2 folosind seria alternantă f(x)=∑(−1)ⁿ⁺¹xⁿ/n, dar din motive numerice se oprește la x=0.99 în loc de x=1 exact. Cât de aproape e această estimare de valoarea reală ln2?","pasi":["Calculăm f(0.99)=ln(1+0.99)=ln(1.99)≈0.688.","Comparăm cu valoarea exactă la limită: ln2≈0.693.","Diferența este mică, de ordinul 0.005, exact pentru că teorema lui Abel garantează că f(x) se apropie continuu de ln2 pe măsură ce x→1⁻ - programul obține o aproximare bună, deși nu evaluează exact la x=1."],"r":"✓ f(0.99)≈<strong>0.688</strong>, foarte aproape de ln2≈0.693"}]};
CONTINUT_ANALIZA["criteriul-integral-convergenta"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie f:[1,∞)→[0,∞) continuă și descrescătoare. Atunci seria ∑f(n) converge dacă și numai dacă integrala improprie ∫₁^∞f(x)dx converge (este finită).</div>",formula_display:"∑f(n) converge ↔ ∫₁^∞f(x)dx converge",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 50,40 C 90,70 150,120 280,155\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><rect x=\"50\" y=\"40\" width=\"35\" height=\"130\" fill=\"#c8922a\" fill-opacity=\"0.45\" stroke=\"#c8922a\" stroke-width=\"1\"/><rect x=\"85\" y=\"65\" width=\"35\" height=\"105\" fill=\"#c8922a\" fill-opacity=\"0.4\" stroke=\"#c8922a\" stroke-width=\"1\"/><rect x=\"120\" y=\"85\" width=\"35\" height=\"85\" fill=\"#c8922a\" fill-opacity=\"0.35\" stroke=\"#c8922a\" stroke-width=\"1\"/><rect x=\"155\" y=\"100\" width=\"35\" height=\"70\" fill=\"#c8922a\" fill-opacity=\"0.3\" stroke=\"#c8922a\" stroke-width=\"1\"/><text x=\"67\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">f(1)</text><text x=\"102\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">f(2)</text><text x=\"137\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">f(3)</text><text x=\"172\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">f(4)</text><text x=\"235\" y=\"60\" font-size=\"11\" fill=\"#4a1a7a\" font-style=\"italic\">f(x)</text><text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">∑f(n) și ∫f(x)dx au aceeași natură</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă înălțimea unui gard de scânduri, tot mai mici, urmărește îndeaproape o curbă lină</span>, aria de sub scânduri e aproape aceeași cu aria de sub curbă. De aceea, suma tuturor scândurilor (seria) și aria de sub curbă (integrala) „se comportă la fel”: ori sunt amândouă finite, ori amândouă infinite.",intuitiv_nota:"Colin Maclaurin a intuit ideea, iar Cauchy a formalizat-o riguros. Criteriul oferă și o estimare a erorii de trunchiere: restul seriei este încadrat de valorile integralei.",exercitii:[{"q":"∑1/n² - aplică criteriul integral.","pasi":["Funcția f(x)=1/x² este pozitivă, continuă și descrescătoare pe [1,∞).","Calculăm integrala improprie: ∫₁^∞1/x²dx=[−1/x]₁^∞=(0)−(−1)=1.","Integrala este finită (1), deci prin criteriu, seria ∑1/n² converge."],"r":"✓ <strong>Convergentă</strong>"},{"q":"∑1/n (seria armonică) - cazul-limită dintre convergență și divergență printre seriile ∑1/nᵖ.","pasi":["Funcția f(x)=1/x este pozitivă, continuă și descrescătoare pe [1,∞).","Calculăm integrala: ∫₁^∞1/x dx=[ln x]₁^∞=∞−0=∞.","Integrala este infinită, deci și seria armonică diverge - exact cazul-limită p=1 dintre seriile ∑1/nᵖ convergente (p&gt;1) și divergente (p≤1)."],"r":"✓ <strong>Divergentă</strong> - cazul-limită p=1"},{"q":"Se știe (fără a cunoaște formula lui f) că seria ∑f(n), cu f continuă, pozitivă și descrescătoare pe [1,∞), diverge. Ce spune criteriul integral despre ∫₁^∞f(x)dx?","pasi":["Criteriul afirmă echivalența: ∑f(n) converge dacă și numai dacă ∫₁^∞f(x)dx converge.","Deoarece ∑f(n) diverge (nu converge), prin echivalență și integrala trebuie să diverge (adică ∫₁^∞f(x)dx=∞).","Concluzia se obține direct din echivalență, fără să cunoaștem formula exactă a lui f."],"r":"✓ Integrala trebuie să fie <strong>divergentă</strong> (∞)"},{"q":"Adevărat sau fals: criteriul integral se poate aplica oricărei funcții pozitive f, indiferent dacă este descrescătoare sau nu.","pasi":["Fals - ipoteza de monotonie (f descrescătoare) este esențială pentru comparația dintre dreptunghiuri și aria de sub curbă.","Fără monotonie, f poate oscila puternic între valorile întregi, iar suma ∑f(n) (care „vede” doar valorile din puncte întregi) se poate comporta complet diferit de aria totală ∫f(x)dx.","Fără această ipoteză, seria și integrala pot avea naturi diferite, deci criteriul nu se mai poate aplica."],"r":"✓ <strong>Fals</strong> - monotonia lui f este o ipoteză obligatorie"},{"q":"Cantitatea de medicament rămasă în sânge la ora întreagă n este f(n)=1/(n+1)² mg, o funcție descrescătoare. Se acumulează, însumând dozele rămase în fiecare oră, o cantitate infinită de-a lungul timpului?","pasi":["Funcția f(x)=1/(x+1)² este pozitivă, continuă și descrescătoare pe [1,∞), deci putem aplica criteriul integral.","Calculăm integrala: ∫₁^∞dx/(x+1)²=[−1/(x+1)]₁^∞=0−(−1/2)=1/2, o valoare finită.","Deoarece integrala este finită, seria ∑f(n) converge - cantitatea totală acumulată rămâne finită, nu crește nemărginit."],"r":"✓ <strong>Nu</strong> - suma totală rămâne finită (converge)"}]};
CONTINUT_ANALIZA["teorema-lui-darboux"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie f derivabilă pe [a,b]. Dacă k este strict între f'(a) și f'(b), atunci există c∈(a,b) cu f'(c)=k - chiar dacă f' nu este continuă.</div>",formula_display:"f'(a) &lt; k &lt; f'(b) → ∃c∈(a,b): f'(c)=k",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"100\" x2=\"300\" y2=\"100\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><path d=\"M 60,150 C 100,130 120,60 140,100 C 155,125 165,75 175,100 C 185,120 195,80 210,60 C 240,40 260,35 280,30\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><circle cx=\"60\" cy=\"150\" r=\"4\" fill=\"#4a1a7a\"/><circle cx=\"280\" cy=\"30\" r=\"4\" fill=\"#4a1a7a\"/><circle cx=\"140\" cy=\"100\" r=\"4.5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"60\" y=\"188\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">a</text><text x=\"280\" y=\"188\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">b</text><text x=\"140\" y=\"188\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\" font-weight=\"600\">c</text><text x=\"22\" y=\"155\" text-anchor=\"end\" font-size=\"10\" fill=\"#555\">f'(a)</text><text x=\"22\" y=\"34\" text-anchor=\"end\" font-size=\"10\" fill=\"#555\">f'(b)</text><text x=\"22\" y=\"104\" text-anchor=\"end\" font-size=\"10\" fill=\"#c8922a\">k</text><text x=\"150\" y=\"15\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">f' trece prin orice k dintre f'(a) și f'(b), chiar discontinuă</text></svg>",intuitiv_text:"<span class=\"hl\">Derivata unei funcții nu poate „sări” peste valori</span>, chiar dacă graficul ei arată întrerupt. Dacă viteza unei mașini a fost −2 la un moment și +3 puțin mai târziu, cu siguranță a trecut, la un moment dat, prin exact 0 - indiferent cât de brusc pare graficul vitezei.",intuitiv_nota:"Jean Gaston Darboux a demonstrat rezultatul în 1875. Exemplul clasic f(x)=x²sin(1/x) are derivată discontinuă în origine, dar aceasta oscilează continuu prin toate valorile apropiate, fără salturi reale. O consecință utilă: dacă f' nu se anulează pe un interval, ea păstrează semn constant, deci f este strict monotonă acolo.",exercitii:[{"q":"f(x)=x² pe [0,2]. Găsește punctul c garantat de Darboux cu f'(c)=3.","pasi":["Calculăm derivata: f'(x)=2x, deci f'(0)=0 și f'(2)=4.","Cum 0&lt;3&lt;4, Darboux garantează existența unui punct c∈(0,2) cu f'(c)=3.","Rezolvăm ecuația 2c=3, deci c=3/2, care se află într-adevăr în intervalul (0,2)."],"r":"✓ c=<strong>3/2</strong>"},{"q":"Fie f derivabilă pe [0,4], cu f'(0)=1. Ce condiție minimă trebuie să satisfacă f'(4) pentru ca Darboux să garanteze un punct c∈(0,4) cu f'(c)=7?","pasi":["Darboux garantează valoarea 7 doar dacă 7 este strict între f'(0) și f'(4).","Cum f'(0)=1&lt;7, e nevoie ca 7 să fie mai mic decât f'(4), adică f'(4) trebuie să fie strict mai mare decât 7.","Orice valoare f'(4)&gt;7 (de exemplu 8) garantează, prin Darboux, existența lui c; dacă f'(4)≤7, teorema nu mai garantează nimic."],"r":"✓ f'(4) trebuie să fie <strong>strict mai mare decât 7</strong>"},{"q":"f(x)=5x+3 pe ℝ (derivată constantă). Ce spune Darboux despre valorile pe care le poate lua f'?","pasi":["Derivata este f'(x)=5, aceeași valoare pentru orice x - nu există niciun interval pe care f'(a) și f'(b) să difere.","Proprietatea Darboux cere ca f' să treacă prin toate valorile strict dintre f'(a) și f'(b); aici acest interval e „gol” (f'(a)=f'(b)=5), deci condiția e satisfăcută trivial.","Acesta e cazul cel mai simplu posibil: o derivată constantă respectă automat proprietatea Darboux, neavând nicio valoare „de sărit”."],"r":"✓ Satisfăcută <strong>trivial</strong> - f' ia o singură valoare, 5"},{"q":"Poate g(x)=−1 pentru x≤0, g(x)=1 pentru x&gt;0 să fie derivata unei funcții f pe ℝ?","pasi":["g are un salt brusc în x=0, de la −1 la 1 (discontinuitate de speța I).","k=0 este strict între valorile −1 și 1 ale lui g, dar g nu ia niciodată efectiv valoarea 0 - sare direct de la −1 la 1.","O adevărată derivată ar trebui să treacă prin 0 (proprietatea Darboux), deci g nu poate fi derivata niciunei funcții f pe ℝ."],"r":"✓ <strong>Nu</strong> - g nu are proprietatea Darboux, deci nu poate fi o derivată"},{"q":"Un automobil pornește cu o eroare de senzor: viteza înregistrată la momentul 0 este v(0)=−2 m/s (recul aparent), iar la momentul 1 secundă este v(1)=3 m/s. Presupunând că v este derivata poziției mașinii (deci derivabilă), arată că mașina a avut cu certitudine, la un moment dat, viteza exact 0.","pasi":["0 este strict între v(0)=−2 și v(1)=3.","Chiar dacă senzorul ar înregistra citiri bruște sau discontinue, v tot rămâne derivata poziției mașinii, deci are proprietatea Darboux.","Prin Darboux, există un moment c∈(0,1) cu v(c)=0 - mașina a fost, la un moment dat, cu adevărat oprită."],"r":"✓ <strong>Da</strong>, garantat de teorema lui Darboux"}]};
CONTINUT_ANALIZA["formula-lui-stirling"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Pentru n→∞, n! este asimptotic egal cu √(2πn)·(n/e)ⁿ, în sensul că raportul celor două expresii tinde la 1.</div>",formula_display:"n! ~ √(2πn)·(n/e)ⁿ, lim_{n→∞} n!/[√(2πn)·(n/e)ⁿ] = 1",diagrama:"<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"300\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"300\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 55,155 C 100,120 160,70 280,25\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.5\"/><path d=\"M 55,160 C 100,122 160,72 280,27\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"5,3\"/><circle cx=\"55\" cy=\"155\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"120\" cy=\"100\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"200\" cy=\"55\" r=\"3.5\" fill=\"#4a1a7a\"/><circle cx=\"280\" cy=\"25\" r=\"3.5\" fill=\"#4a1a7a\"/><text x=\"55\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">n=1</text><text x=\"200\" y=\"185\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">n=10</text><text x=\"215\" y=\"45\" font-size=\"10\" fill=\"#4a1a7a\">ln(n!) exact</text><text x=\"215\" y=\"90\" font-size=\"10\" fill=\"#c8922a\">aproximarea Stirling</text><text x=\"150\" y=\"15\" text-anchor=\"middle\" font-size=\"10\" fill=\"#999\">curbele se apropie pe măsură ce n crește</text></svg>",intuitiv_text:"<span class=\"hl\">Dacă tot înmulțești numere tot mai mari - 1×2×3×4×...×n - rezultatul crește amețitor de repede</span>. Stirling a găsit o formulă simplă care „ghicește” cât de mare va fi acest produs uriaș, fără să-l calculezi efectiv - și cu cât n e mai mare, cu atât ghicitul e mai exact procentual.",intuitiv_nota:"James Stirling a publicat formula în 1730. E esențială în combinatorică (aproximarea coeficienților binomiali), mecanica statistică (entropia Boltzmann) și teoria probabilităților (aproximarea distribuției binomiale).",exercitii:[{"q":"Aproximează 10! cu formula lui Stirling și compară cu valoarea exactă, 3628800.","pasi":["Calculăm factorul de corecție: √(2π·10)=√(62.83)≈7.927.","Calculăm partea dominantă: (10/e)¹⁰=10¹⁰/e¹⁰≈10000000000/22026.47≈453999.3.","Înmulțim cele două părți: 7.927×453999.3≈3598700, foarte aproape de valoarea exactă 3628800 (eroare relativă sub 1%)."],"r":"✓ ≈<strong>3.5987×10⁶</strong>, eroare relativă ≈<strong>0.84%</strong>"},{"q":"Care este cel mai mic n natural pentru care partea dominantă a lui Stirling, (n/e)ⁿ, depășește 10⁶?","pasi":["Partea dominantă a aproximării Stirling este (n/e)ⁿ; factorul √(2πn) e doar o corecție mai mică.","Pentru n=10: (10/e)¹⁰≈453999, sub 10⁶.","Pentru n=11: (11/e)¹¹≈4.77 milioane, peste 10⁶. Deci cel mai mic n cu (n/e)ⁿ&gt;10⁶ este n=11."],"r":"✓ n=<strong>11</strong>"},{"q":"Aplică formula lui Stirling la cel mai mic caz posibil, n=1, și compară cu valoarea exactă 1!=1.","pasi":["Calculăm aproximarea: √(2π·1)·(1/e)¹=√(2π)·(1/e)≈2.5066×0.3679≈0.922.","Comparăm cu valoarea exactă: 1!=1.","Eroarea relativă este (1−0.922)/1≈7.8% - mult mai mare decât eroarea de sub 1% obținută la n=10, ceea ce arată că formula devine din ce în ce mai precisă abia pentru n mare, nu pentru n mic."],"r":"✓ Aproximare ≈<strong>0.922</strong>, eroare ≈<strong>7.8%</strong> - mult mai slabă decât la n mare"},{"q":"Adevărat sau fals: pe măsură ce n crește, precizia relativă (procentuală) a aproximării lui Stirling se îmbunătățește, deși diferența absolută dintre n! și aproximare poate crește foarte mult.","pasi":["Adevărat. Definiția asimptotică spune că raportul n!/aproximare tinde la 1, adică eroarea relativă (procentuală) tinde la 0.","Totuși, n! crește atât de repede încât chiar și o eroare relativă minusculă, aplicată unui număr uriaș, poate însemna o diferență absolută enormă.","Cele două lucruri nu se contrazic: eroarea absolută poate crește nemărginit, în timp ce eroarea relativă scade constant spre 0."],"r":"✓ <strong>Adevărat</strong> - eroarea relativă scade, deși eroarea absolută poate crește"},{"q":"Estimează probabilitatea de a obține exact 50 steme din 100 aruncări ale unei monede corecte, P=C(100,50)/2¹⁰⁰, folosind Stirling.","pasi":["Aplicăm Stirling la (2n)! și (n!)², cu n=50: (2n)!~√(4πn)·(2n/e)²ⁿ și (n!)²~2πn·(n/e)²ⁿ, deci C(2n,n)=(2n)!/(n!)²~4ⁿ/√(πn).","Pentru n=50: C(100,50)/2¹⁰⁰~1/√(50π)=1/√157.08≈1/12.53.","Calculăm: 1/12.53≈0.0798, adică aproximativ 7.98%."],"r":"✓ P≈<strong>0.0798</strong> (≈7.98%)"}]};
CONTINUT_ANALIZA["teorema-lui-dini"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Fie (fₙ) un șir de funcții continue pe un compact K, convergent punctual și monoton (crescător sau descrescător) către o funcție f continuă pe K. Atunci convergența fₙ→f este uniformă.</div>",formula_display:"fₙ↘f monoton, f continuă pe compact → convergență uniformă",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\" width=\"280\"><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"20\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"170\" x2=\"270\" y2=\"170\" stroke=\"#4a1a7a\" stroke-width=\"1.5\"/><path d=\"M 40,170 C 120,169 200,165 240,120 C 255,90 260,50 260,30\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1.5\" opacity=\"0.4\"/><path d=\"M 40,170 C 150,169 220,150 245,90 C 252,65 255,45 255,30\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"1.8\" opacity=\"0.6\"/><path d=\"M 40,170 C 180,169.5 230,140 248,55 C 251,42 252,32 252,30\" fill=\"none\" stroke=\"#4a1a7a\" stroke-width=\"2.2\" opacity=\"0.85\"/><line x1=\"250\" y1=\"170\" x2=\"250\" y2=\"30\" stroke=\"#c8922a\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/><circle cx=\"250\" cy=\"170\" r=\"3.5\" fill=\"#c8922a\"/><circle cx=\"250\" cy=\"30\" r=\"4.5\" fill=\"#c8922a\" stroke=\"#fff\" stroke-width=\"1.5\"/><text x=\"40\" y=\"185\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">0</text><text x=\"250\" y=\"185\" text-anchor=\"middle\" font-size=\"11\" fill=\"#555\" font-style=\"italic\">1</text><text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">fₙ(x)=xⁿ: curbele „cad” tot mai brusc spre o limită discontinuă</text></svg>",intuitiv_text:"<span class=\"hl\">Imaginează-ți mai multe fire elastice care se apropie tot mai mult de o formă țintă, fiecare mișcându-se lin, în aceeași direcție, fără să treacă unul peste altul</span>. Dacă forma-țintă e și ea netedă, fără sărituri, și spațiul în care se mișcă e mărginit, atunci toate firele ajung aproape de țintă în același timp, peste tot deodată - nu doar punct cu punct, pe rând.",intuitiv_nota:"Ulisse Dini a demonstrat rezultatul în 1878. Toate cele trei ipoteze - continuitatea termenilor, monotonia și compactitatea - sunt esențiale; eliminarea oricăreia produce contraexemple clasice de convergență neuniformă.",exercitii:[{"q":"fₙ(x)=√(x²+1/n) pe [−1,1]. Verifică ipotezele lui Dini și stabilește dacă fₙ→f este uniformă.","pasi":["Fiecare fₙ este continuă pe compactul [−1,1].","Șirul este monoton descrescător în n: fₙ₊₁(x)≤fₙ(x) pentru orice x, pentru că 1/(n+1)&lt;1/n.","Limita punctuală este f(x)=|x| (deoarece 1/n→0), continuă pe [−1,1]; toate ipotezele lui Dini fiind satisfăcute, convergența este uniformă."],"r":"✓ <strong>Da</strong>, convergența e uniformă"},{"q":"Se știe că (fₙ) e un șir de funcții continue, monoton descrescător, pe compactul [0,1], dar convergența la limita punctuală f NU este uniformă. Ce se poate deduce despre f?","pasi":["Teorema lui Dini spune: dacă fₙ continue, monoton, pe compact, și limita f e continuă, atunci convergența este automat uniformă.","Aici avem toate celelalte ipoteze satisfăcute (continuitate, monotonie, compactitate), dar concluzia (convergența uniformă) nu are loc.","Dacă f ar fi fost continuă, Dini ar fi garantat uniformitatea - contrar ipotezei date. Deci, prin reducere la absurd, f nu poate fi continuă pe [0,1]."],"r":"✓ <strong>f nu poate fi continuă</strong> pe [0,1]"},{"q":"fₙ(x)=xⁿ pe [0,1]. Se aplică Dini?","pasi":["Pentru x fixat în [0,1], șirul xⁿ este descrescător în n, deci monotonia e satisfăcută.","Limita punctuală este f(x)=0 pentru x&lt;1 și f(1)=1 - o funcție discontinuă exact în x=1.","Ipoteza de continuitate a limitei f nu este satisfăcută, deci Dini nu se aplică; și, într-adevăr, convergența nu este uniformă aici."],"r":"✓ <strong>Nu se aplică</strong> (limita nu e continuă); convergența chiar nu e uniformă"},{"q":"Adevărat sau fals: dacă (fₙ) e monoton descrescător, cu termeni continui și limită continuă f pe un interval I, convergența e mereu uniformă, indiferent dacă I este mărginit sau nu.","pasi":["Fals - ipoteza de compactitate (interval închis și mărginit) este esențială, nu doar continuitatea și monotonia.","Contraexemplu: fₙ(x)=x²/(x²+n) pe ℝ (necompact). Șirul e descrescător, continuu, cu limita f≡0, continuă.","Totuși sup_{x∈ℝ}fₙ(x)=1 pentru orice n (atins când x→∞), deci convergența NU este uniformă - lipsa compactității strică garanția lui Dini."],"r":"✓ <strong>Fals</strong> - mărginirea (compactitatea) domeniului este de asemenea esențială"},{"q":"Un impuls de căldură se propagă printr-o bară: temperatura suplimentară la poziția x, după n secunde, este Tₙ(x)=n·x·e^(−nx) (grade, x∈[0,1]). În fiecare punct fix, temperatura suplimentară tinde spre 0, dar „vârful” impulsului rămâne mereu la fel de intens. Dispare temperatura suplimentară uniform, peste tot deodată?","pasi":["Pentru x fixat, Tₙ(x)=n·x·e^(−nx)→0 când n→∞ (exponențiala „câștigă” în fața lui n), deci limita punctuală este f≡0.","Dar la punctul xₙ=1/n, avem Tₙ(1/n)=n·(1/n)·e⁻¹=e⁻¹≈0.368, indiferent cât de mare este n.","Deci sup Tₙ nu tinde la 0, ci rămâne mereu ≈0.368 - convergența nu e uniformă; vârful impulsului „călătorește” spre x=0 fără să-și piardă intensitatea (și, de altfel, (Tₙ) nici nu e monoton, deci Dini nu se putea aplica oricum)."],"r":"✓ <strong>Nu</strong> - convergența nu e uniformă (vârful impulsului rămâne la fel de intens)"}]};
